// Ejercicio 01: SoundWave - Iterator (R1) + Command (R4)
import java.util.*;
interface Iterador { boolean hayMas(); String siguiente(); }
class IteradorOrden implements Iterador {
    private final Playlist playlist;
    private int i = 0;
    IteradorOrden(Playlist playlist) { this.playlist = playlist; }
    public boolean hayMas() { return i < playlist.canciones.size(); }
    public String siguiente() { String c = playlist.canciones.get(i); i++; return c; }
}
class IteradorInverso implements Iterador {
    private final Playlist playlist;
    private int i;
    IteradorInverso(Playlist playlist) { this.playlist = playlist; this.i = playlist.canciones.size() - 1; }
    public boolean hayMas() { return i >= 0; }
    public String siguiente() { String c = playlist.canciones.get(i); i--; return c; }
}
class IteradorAleatorio implements Iterador {
    private final List<String> mezcladas = new ArrayList<>();
    private int i = 0;
    IteradorAleatorio(Playlist playlist) {
        List<String> pendientes = new ArrayList<>(playlist.canciones);
        while (pendientes.size() > 0) {
            int pos = (int) (Math.random() * pendientes.size());
            mezcladas.add(pendientes.remove(pos));
        }
    }
    public boolean hayMas() { return i < mezcladas.size(); }
    public String siguiente() { String c = mezcladas.get(i); i++; return c; }
}
class Playlist {
    final List<String> canciones = new ArrayList<>();
    Iterador orden() { return new IteradorOrden(this); }
    Iterador inverso() { return new IteradorInverso(this); }
    Iterador aleatorio() { return new IteradorAleatorio(this); }
}
interface Comando { void ejecutar(); void deshacer(); }
class AgregarACola implements Comando {
    private final Playlist cola;
    private final String cancion;
    AgregarACola(Playlist cola, String cancion) { this.cola = cola; this.cancion = cancion; }
    public void ejecutar() { cola.canciones.add(cancion); }
    public void deshacer() { cola.canciones.remove(cola.canciones.size() - 1); }
}
class Reloj {
    private final List<Comando> historial = new ArrayList<>();
    void pulsar(Comando c) {
        c.ejecutar();
        historial.add(c);
    }
    void deshacer() {
        if (historial.size() > 0) {
            Comando ultimo = historial.remove(historial.size() - 1);
            ultimo.deshacer();
        }
    }
}
public class Main {
    static String recorrer(Iterador it) {
        StringBuilder sb = new StringBuilder();
        while (it.hayMas()) {
            sb.append(it.siguiente()).append(" ");
        }
        return sb.toString().trim();
    }
    static String unir(List<String> lista) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < lista.size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(lista.get(i));
        }
        return sb.toString();
    }
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Iterator) ===");
        Playlist p = new Playlist();
        p.canciones.add("A");
        p.canciones.add("B");
        p.canciones.add("C");
        p.canciones.add("D");
        System.out.println(recorrer(p.orden()) + " · " + recorrer(p.inverso()));
        String azar = recorrer(p.aleatorio());
        String[] partes = azar.split(" ");
        HashSet<String> distintas = new HashSet<>();
        for (int i = 0; i < partes.length; i++) {
            distintas.add(partes[i]);
        }
        boolean sinRepetir = partes.length == 4 && distintas.size() == 4;
        System.out.println("Aleatorio: " + azar + " (sin repetir: " + sinRepetir + ")");
        System.out.println("\n=== Caso 4 · Req. 4 (Command) ===");
        Playlist cola = new Playlist();
        Reloj reloj = new Reloj();
        reloj.pulsar(new AgregarACola(cola, "B"));
        reloj.pulsar(new AgregarACola(cola, "C"));
        System.out.print("Cola antes de deshacer: " + unir(cola.canciones));
        reloj.deshacer();
        System.out.println(" · después: " + unir(cola.canciones));
    }
}

// Ejercicio 02: Banco Andino - Chain of Responsibility (R1) + Singleton (R3)
import java.util.*;
class Auditoria {
    private static final Auditoria INSTANCIA = new Auditoria();
    final List<String> lineas = new ArrayList<>();
    private Auditoria() { }
    static Auditoria getInstancia() { return INSTANCIA; }
}
class Aprobador {
    private final String nombre;
    private final int limite;
    private final Aprobador siguiente;
    Aprobador(String nombre, int limite, Aprobador siguiente) {
        this.nombre = nombre;
        this.limite = limite;
        this.siguiente = siguiente;
    }
    String aprobar(int monto) {
        if (monto <= limite) {
            return "Aprobado por " + nombre;
        }
        if (siguiente == null) {
            return "Rechazado";
        }
        return siguiente.aprobar(monto);
    }
    Auditoria registro() { return Auditoria.getInstancia(); }
}
class Cuentas {
    Auditoria registro() { return Auditoria.getInstancia(); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Chain of Responsibility) ===");
        Aprobador comite = new Aprobador("comité", 500000, null);
        Aprobador gerente = new Aprobador("gerente", 50000, comite);
        Aprobador ejecutivo = new Aprobador("ejecutivo", 5000, gerente);
        System.out.println(ejecutivo.aprobar(3000) + " · " + ejecutivo.aprobar(20000) + " · " + ejecutivo.aprobar(120000) + " · " + ejecutivo.aprobar(800000));
        System.out.println("\n=== Caso 3 · Req. 3 (Singleton) ===");
        Cuentas cuentas = new Cuentas();
        Auditoria desdePrestamos = ejecutivo.registro();
        Auditoria desdeCuentas = cuentas.registro();
        desdePrestamos.lineas.add("Préstamo aprobado");
        desdeCuentas.lineas.add("Cuenta abierta");
        System.out.println("¿Mismo registro? " + (desdePrestamos == desdeCuentas) + " · Líneas: " + desdePrestamos.lineas.size());
    }
}

// Ejercicio 03: Reinos de Eldoria - State (R3) + Memento (R4)
interface EstadoHeroe {
    String moverse(Heroe h, int dx, int dy);
    void pasarTurno(Heroe h);
    void usarAntidoto(Heroe h);
    String nombre();
}
class EstadoNormal implements EstadoHeroe {
    public String moverse(Heroe h, int dx, int dy) { h.x += dx; h.y += dy; return "Te mueves"; }
    public void pasarTurno(Heroe h) { }
    public void usarAntidoto(Heroe h) { }
    public String nombre() { return "Normal"; }
}
class EstadoEnvenenado implements EstadoHeroe {
    public String moverse(Heroe h, int dx, int dy) { h.x += dx; h.y += dy; return "Te mueves envenenado"; }
    public void pasarTurno(Heroe h) { h.vida -= 5; }
    public void usarAntidoto(Heroe h) { h.estado = new EstadoNormal(); }
    public String nombre() { return "Envenenado"; }
}
class EstadoCongelado implements EstadoHeroe {
    private int turnos = 2;
    public String moverse(Heroe h, int dx, int dy) { return "No puedes moverte: estás congelado"; }
    public void pasarTurno(Heroe h) { if (--turnos == 0) h.estado = new EstadoNormal(); }
    public void usarAntidoto(Heroe h) { }
    public String nombre() { return "Congelado"; }
}
class Heroe {
    int vida, x, y;
    EstadoHeroe estado = new EstadoNormal();
    Heroe(int vida, int x, int y) { this.vida = vida; this.x = x; this.y = y; }
    String moverse(int dx, int dy) { return estado.moverse(this, dx, dy); }
    void pasarTurno() { estado.pasarTurno(this); }
    void usarAntidoto() { estado.usarAntidoto(this); }
    void envenenar() { estado = new EstadoEnvenenado(); }
    void congelar() { estado = new EstadoCongelado(); }
    String condicion() { return estado.nombre(); }
    Memento guardar() { return new Memento(vida, x, y); }
    void restaurar(Memento m) { vida = m.vida; x = m.x; y = m.y; }
    static class Memento {
        private final int vida, x, y;
        private Memento(int vida, int x, int y) { this.vida = vida; this.x = x; this.y = y; }
    }
}
class Mundo {
    private Heroe.Memento fogata;
    void descansarEnFogata(Heroe h) { fogata = h.guardar(); }
    void revivir(Heroe h) { h.restaurar(fogata); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 3 · Req. 3 (State) ===");
        Heroe h = new Heroe(100, 0, 0);
        h.envenenar(); h.pasarTurno(); h.pasarTurno(); h.usarAntidoto();
        System.out.println("Vida " + h.vida + " · vuelve a " + h.condicion());
        h.congelar();
        System.out.println(h.moverse(1, 0));
        System.out.println("\n=== Caso 4 · Req. 4 (Memento) ===");
        Mundo mundo = new Mundo();
        Heroe g = new Heroe(80, 10, 5);
        mundo.descansarEnFogata(g);
        while (g.vida > 0) g.vida -= 30;
        mundo.revivir(g);
        System.out.println("El héroe reaparece con vida " + g.vida + " en la posición (" + g.x + ", " + g.y + ")");
    }
}

// Ejercicio 04: DocuWrite - Command (R1) + Composite (R2)
import java.util.*;
interface Elemento { int palabras(); }
class Parrafo implements Elemento {
    final StringBuilder texto = new StringBuilder();
    boolean negrita = false;
    public int palabras() {
        String t = texto.toString().trim();
        if (t.length() == 0) {
            return 0;
        }
        return t.split(" +").length;
    }
}
class Imagen implements Elemento {
    public int palabras() { return 0; }
}
class Seccion implements Elemento {
    final List<Elemento> partes = new ArrayList<>();
    public int palabras() {
        int total = 0;
        for (int i = 0; i < partes.size(); i++) {
            total += partes.get(i).palabras();
        }
        return total;
    }
}
interface Comando { void ejecutar(); void deshacer(); }
class Escribir implements Comando {
    private final Parrafo parrafo;
    private final String texto;
    Escribir(Parrafo parrafo, String texto) { this.parrafo = parrafo; this.texto = texto; }
    public void ejecutar() { parrafo.texto.append(texto); }
    public void deshacer() { parrafo.texto.setLength(parrafo.texto.length() - texto.length()); }
}
class Borrar implements Comando {
    private final Parrafo parrafo;
    private final int cantidad;
    private String borrado = "";
    Borrar(Parrafo parrafo, int cantidad) { this.parrafo = parrafo; this.cantidad = cantidad; }
    public void ejecutar() {
        int inicio = Math.max(0, parrafo.texto.length() - cantidad);
        borrado = parrafo.texto.substring(inicio);
        parrafo.texto.setLength(inicio);
    }
    public void deshacer() { parrafo.texto.append(borrado); }
}
class AplicarNegrita implements Comando {
    private final Parrafo parrafo;
    private boolean anterior;
    AplicarNegrita(Parrafo parrafo) { this.parrafo = parrafo; }
    public void ejecutar() { anterior = parrafo.negrita; parrafo.negrita = true; }
    public void deshacer() { parrafo.negrita = anterior; }
}
class Macro implements Comando {
    private final List<Comando> pasos = new ArrayList<>();
    void agregar(Comando c) { pasos.add(c); }
    public void ejecutar() {
        for (int i = 0; i < pasos.size(); i++) {
            pasos.get(i).ejecutar();
        }
    }
    public void deshacer() {
        for (int i = pasos.size() - 1; i >= 0; i--) {
            pasos.get(i).deshacer();
        }
    }
}
class Editor {
    private final List<Comando> hechos = new ArrayList<>();
    private final List<Comando> deshechos = new ArrayList<>();
    void ejecutar(Comando c) {
        c.ejecutar();
        hechos.add(c);
        deshechos.clear();
    }
    void deshacer() {
        if (hechos.size() > 0) {
            Comando c = hechos.remove(hechos.size() - 1);
            c.deshacer();
            deshechos.add(c);
        }
    }
    void rehacer() {
        if (deshechos.size() > 0) {
            Comando c = deshechos.remove(deshechos.size() - 1);
            c.ejecutar();
            hechos.add(c);
        }
    }
}
public class Main {
    static Parrafo parrafo(int palabras) {
        Parrafo p = new Parrafo();
        for (int i = 0; i < palabras; i++) {
            p.texto.append("a ");
        }
        return p;
    }
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Command) ===");
        Parrafo p = new Parrafo();
        Editor editor = new Editor();
        editor.ejecutar(new Escribir(p, "Hola"));
        editor.ejecutar(new Escribir(p, " mundo"));
        editor.deshacer();
        System.out.print("Tras deshacer: " + p.texto);
        editor.rehacer();
        System.out.println(" · tras rehacer: " + p.texto);
        System.out.println("\n=== Caso 2 · Req. 2 (Composite) ===");
        Seccion subseccion = new Seccion();
        subseccion.partes.add(parrafo(80));
        Seccion seccion = new Seccion();
        seccion.partes.add(parrafo(120));
        seccion.partes.add(new Imagen());
        seccion.partes.add(subseccion);
        System.out.println("Sección: " + seccion.palabras() + " palabras · Subsección: " + subseccion.palabras() + " palabras");
    }
}

// Ejercicio 05: Hospital San Rafael - State (R2) + Chain of Responsibility (R4)
class Nivel {
    private final String nombre;
    private final int maxGravedad;
    private final Nivel siguiente;
    Nivel(String nombre, int maxGravedad, Nivel siguiente) {
        this.nombre = nombre;
        this.maxGravedad = maxGravedad;
        this.siguiente = siguiente;
    }
    String atender(int gravedad) {
        if (gravedad <= maxGravedad) {
            return nombre;
        }
        if (siguiente == null) {
            return "Sin nivel disponible";
        }
        return siguiente.atender(gravedad);
    }
}
abstract class Etapa {
    abstract String nombre();
    Etapa triar() { return rechazar("triar"); }
    Etapa atender() { return rechazar("atender"); }
    Etapa darAlta() { return rechazar("dar de alta"); }
    Etapa hospitalizar() { return rechazar("hospitalizar"); }
    private Etapa rechazar(String accion) {
        System.out.println("Rechazado: no se puede " + accion + " en " + nombre());
        return this;
    }
}
class EnTriaje extends Etapa {
    String nombre() { return "En triaje"; }
    Etapa triar() { return new EnEspera(); }
}
class EnEspera extends Etapa {
    String nombre() { return "En espera"; }
    Etapa atender() { return new EnAtencion(); }
}
class EnAtencion extends Etapa {
    String nombre() { return "En atención"; }
    Etapa darAlta() { return new Alta(); }
    Etapa hospitalizar() { return new Hospitalizado(); }
}
class Alta extends Etapa {
    String nombre() { return "Alta"; }
}
class Hospitalizado extends Etapa {
    String nombre() { return "Hospitalizado"; }
}
class Paciente {
    private Etapa etapa = new EnTriaje();
    final String atiende;
    Paciente(int gravedad, Nivel triaje) { atiende = triaje.atender(gravedad); }
    String etapa() { return etapa.nombre(); }
    void triar() { etapa = etapa.triar(); }
    void atender() { etapa = etapa.atender(); }
    void darAlta() { etapa = etapa.darAlta(); }
    void hospitalizar() { etapa = etapa.hospitalizar(); }
}
public class Main {
    public static void main(String[] args) {
        Nivel especialista = new Nivel("Especialista de guardia", 5, null);
        Nivel general = new Nivel("Médico general", 3, especialista);
        Nivel triaje = new Nivel("Enfermera de triaje", 2, general);
        System.out.println("=== Caso 2 · Req. 2 (State) ===");
        Paciente a = new Paciente(1, triaje);
        System.out.print(a.etapa());
        a.triar();
        System.out.print(" → " + a.etapa());
        a.atender();
        System.out.print(" → " + a.etapa());
        a.darAlta();
        System.out.println(" → " + a.etapa());
        Paciente b = new Paciente(1, triaje);
        b.triar();
        System.out.println("Otro paciente (" + b.etapa() + ") intenta darse de alta:");
        b.darAlta();
        System.out.println("\n=== Caso 4 · Req. 4 (Chain of Responsibility) ===");
        Paciente g2 = new Paciente(2, triaje);
        Paciente g3 = new Paciente(3, triaje);
        Paciente g5 = new Paciente(5, triaje);
        System.out.println(g2.atiende + " · " + g3.atiende + " · " + g5.atiende);
    }
}

// Ejercicio 06: MercadoSur - Strategy (R2) + Decorator (R4)
interface Pago {
    String nombre();
    int total(int centavos);
}
class Tarjeta implements Pago {
    public String nombre() { return "Tarjeta"; }
    public int total(int centavos) { return centavos + centavos * 3 / 100; }
}
class Transferencia implements Pago {
    public String nombre() { return "Transferencia"; }
    public int total(int centavos) { return centavos; }
}
class ContraEntrega implements Pago {
    public String nombre() { return "Contra entrega"; }
    public int total(int centavos) { return centavos + 500; }
}
abstract class Producto {
    abstract String descripcion();
    abstract int precio();
    int pagar(Pago pago) { return pago.total(precio()); }
}
class Basico extends Producto {
    private final String nombre;
    private final int precio;
    Basico(String nombre, int precio) { this.nombre = nombre; this.precio = precio; }
    String descripcion() { return nombre; }
    int precio() { return precio; }
}
abstract class Extra extends Producto {
    final Producto base;
    Extra(Producto base) { this.base = base; }
}
class Envoltura extends Extra {
    Envoltura(Producto base) { super(base); }
    String descripcion() { return base.descripcion() + " + Envoltura de regalo"; }
    int precio() { return base.precio() + 300; }
}
class Garantia extends Extra {
    Garantia(Producto base) { super(base); }
    String descripcion() { return base.descripcion() + " + Garantía extendida"; }
    int precio() { return base.precio() + 1500; }
}
class Seguro extends Extra {
    Seguro(Producto base) { super(base); }
    String descripcion() { return base.descripcion() + " + Seguro de envío"; }
    int precio() { return base.precio() + 200; }
}
public class Main {
    static String dinero(int centavos) {
        int resto = centavos % 100;
        String ceros = "";
        if (resto < 10) {
            ceros = "0";
        }
        return "$$" + (centavos / 100) + "." + ceros + resto;
    }
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (Strategy) ===");
        Producto pedido = new Basico("Pedido", 20000);
        Pago[] pagos = { new Tarjeta(), new Transferencia(), new ContraEntrega() };
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < pagos.length; i++) {
            if (i > 0) sb.append(" · ");
            sb.append(pagos[i].nombre()).append(": ").append(dinero(pedido.pagar(pagos[i])));
        }
        System.out.println(sb);
        System.out.println("\n=== Caso 4 · Req. 4 (Decorator) ===");
        Producto audifonos = new Basico("Audífonos", 5000);
        Producto conEnvoltura = new Envoltura(audifonos);
        Producto completo = new Seguro(conEnvoltura);
        System.out.println(completo.descripcion() + " -> " + dinero(completo.precio()));
    }
}

// Ejercicio 07: NubeBox - Composite (R1) + Proxy (R2)
import java.util.*;
abstract class ElementoNube {
    final String nombre;
    ElementoNube(String nombre) { this.nombre = nombre; }
    abstract int tamanioMB();
}
abstract class Archivo extends ElementoNube {
    private final int mb;
    Archivo(String nombre, int mb) {
        super(nombre);
        this.mb = mb;
    }
    int tamanioMB() { return mb; }
    abstract String abrir(String usuario);
}
class Carpeta extends ElementoNube {
    private final List<ElementoNube> hijos = new ArrayList<>();
    Carpeta(String nombre) { super(nombre); }
    Carpeta agregar(ElementoNube e) {
        hijos.add(e);
        return this;
    }
    int tamanioMB() {
        int total = 0;
        for (ElementoNube e : hijos) {
            total = total + e.tamanioMB();
        }
        return total;
    }
}
class ArchivoReal extends Archivo {
    ArchivoReal(String nombre, int mb) { super(nombre, mb); }
    String abrir(String usuario) { return usuario + " abre " + nombre; }
}
class ArchivoProxy extends Archivo {
    private final String duenio;
    private final List<String> conPermiso = new ArrayList<>();
    private ArchivoReal real;
    ArchivoProxy(String nombre, int mb, String duenio) {
        super(nombre, mb);
        this.duenio = duenio;
    }
    void darPermiso(String usuario) { conPermiso.add(usuario); }
    String abrir(String usuario) {
        if (!usuario.equals(duenio) && !conPermiso.contains(usuario)) {
            return "Acceso denegado para " + usuario;
        }
        if (real == null) {
            System.out.println("[Descargando " + nombre + "]");
            real = new ArchivoReal(nombre, tamanioMB());
        }
        return real.abrir(usuario);
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Composite) ===");
        Archivo a = new ArchivoReal("a.jpg", 2);
        Archivo b = new ArchivoReal("b.jpg", 3);
        Archivo c = new ArchivoReal("c.jpg", 5);
        Carpeta c2024 = new Carpeta("2024");
        c2024.agregar(c);
        Carpeta fotos = new Carpeta("Fotos");
        fotos.agregar(a);
        fotos.agregar(b);
        fotos.agregar(c2024);
        ElementoNube[] elementos = {fotos, c2024, a};
        StringBuilder linea = new StringBuilder();
        for (int i = 0; i < elementos.length; i++) {
            if (i > 0) {
                linea.append(" · ");
            }
            linea.append(elementos[i].nombre + ": " + elementos[i].tamanioMB() + " MB");
        }
        System.out.println(linea);

        System.out.println("\n=== Caso 2 · Req. 2 (Proxy) ===");
        ArchivoProxy video = new ArchivoProxy("video.mp4", 500, "Dueño");
        video.darPermiso("Luis");
        Carpeta videos = new Carpeta("Videos");
        videos.agregar(video);
        System.out.println("Listar " + videos.nombre + ": " + videos.tamanioMB() + " MB (sin descargar)");
        System.out.println(video.abrir("Dueño"));
        System.out.println(video.abrir("Dueño"));
        System.out.println(video.abrir("Luis"));
        System.out.println(video.abrir("Invitado"));
    }
}

// Ejercicio 08: CasaViva - Adapter (R1) + Bridge (R4)
class LumiTech {
    int brillo;
    void fijarBrillo(int brillo) { this.brillo = brillo; }
}
abstract class Dispositivo {
    int nivel;
    void encender() { ajustarNivel(100); }
    void apagar() { ajustarNivel(0); }
    void ajustarNivel(int nivel) { this.nivel = nivel; }
    abstract String estado();
}
class BombillaLumiTech extends Dispositivo {
    private final LumiTech lib = new LumiTech();
    void ajustarNivel(int nivel) {
        super.ajustarNivel(nivel);
        lib.fijarBrillo(nivel * 255 / 100);
    }
    String estado() { return "LumiTech: brillo " + lib.brillo; }
}
class Parlante extends Dispositivo {
    String estado() { return "Parlante: nivel " + nivel; }
}
class Ventilador extends Dispositivo {
    String estado() {
        if (nivel == 0) {
            return "Ventilador: apagado";
        }
        return "Ventilador: encendido";
    }
}
class Control {
    final Dispositivo dispositivo;
    Control(Dispositivo dispositivo) { this.dispositivo = dispositivo; }
    void encender() { dispositivo.encender(); }
    void apagar() { dispositivo.apagar(); }
}
class ControlAvanzado extends Control {
    ControlAvanzado(Dispositivo dispositivo) { super(dispositivo); }
    void subir() { dispositivo.ajustarNivel(Math.min(100, dispositivo.nivel + 10)); }
    void bajar() { dispositivo.ajustarNivel(Math.max(0, dispositivo.nivel - 10)); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Adapter) ===");
        Dispositivo bombilla = new BombillaLumiTech();
        bombilla.ajustarNivel(50);
        String conNivel50 = bombilla.estado();
        bombilla.apagar();
        System.out.println(conNivel50 + " · " + bombilla.estado());

        System.out.println("\n=== Caso 4 · Req. 4 (Bridge) ===");
        Dispositivo parlante = new Parlante();
        Dispositivo ventilador = new Ventilador();
        parlante.ajustarNivel(30);
        ventilador.encender();
        ControlAvanzado avanzado = new ControlAvanzado(parlante);
        avanzado.subir();
        avanzado.subir();
        Control basico = new Control(ventilador);
        basico.apagar();
        System.out.println(parlante.estado() + " · " + ventilador.estado());
    }
}

// Ejercicio 09: ViajaFácil - Builder (R1) + Prototype (R2)
interface Prototipo<T> {
    T clonar();
}
class PaqueteTuristico implements Prototipo<PaqueteTuristico> {
    final String destino;
    String salida, regreso;
    int vuelo, noches, precioNoche, traslados, tours, seguro;
    PaqueteTuristico(String destino, String salida, String regreso) {
        this.destino = destino;
        this.salida = salida;
        this.regreso = regreso;
    }
    public PaqueteTuristico clonar() {
        PaqueteTuristico copia = new PaqueteTuristico(destino, salida, regreso);
        copia.vuelo = vuelo;
        copia.noches = noches;
        copia.precioNoche = precioNoche;
        copia.traslados = traslados;
        copia.tours = tours;
        copia.seguro = seguro;
        return copia;
    }
    int precio() { return vuelo + noches * precioNoche + traslados + tours + seguro; }
}
class PaqueteBuilder {
    private final PaqueteTuristico paquete;
    PaqueteBuilder(String destino, String salida, String regreso) {
        paquete = new PaqueteTuristico(destino, salida, regreso);
    }
    PaqueteBuilder vuelo(int precio) {
        paquete.vuelo = precio;
        return this;
    }
    PaqueteBuilder hotel(int noches, int precioNoche) {
        paquete.noches = noches;
        paquete.precioNoche = precioNoche;
        return this;
    }
    PaqueteBuilder traslados(int precio) {
        paquete.traslados = precio;
        return this;
    }
    PaqueteBuilder tours(int precio) {
        paquete.tours = precio;
        return this;
    }
    PaqueteBuilder seguro(int precio) {
        paquete.seguro = precio;
        return this;
    }
    PaqueteTuristico build() { return paquete; }
}
class DirectorPaquetes {
    PaqueteTuristico escapada(String destino, String salida, String regreso, int vuelo, int precioNoche) {
        PaqueteBuilder builder = new PaqueteBuilder(destino, salida, regreso);
        builder.vuelo(vuelo);
        builder.hotel(2, precioNoche);
        return builder.build();
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Builder) ===");
        PaqueteBuilder builder = new PaqueteBuilder("Cusco", "2025-06-10", "2025-06-13");
        builder.vuelo(300);
        builder.hotel(3, 80);
        PaqueteTuristico cusco = builder.build();
        DirectorPaquetes director = new DirectorPaquetes();
        PaqueteTuristico paracas = director.escapada("Paracas", "2025-06-20", "2025-06-22", 150, 100);
        System.out.println("Cusco: $$" + cusco.precio() + " · Paracas: $$" + paracas.precio());

        System.out.println("\n=== Caso 2 · Req. 2 (Prototype) ===");
        PaqueteTuristico copia = cusco.clonar();
        copia.salida = "2025-09-01";
        copia.regreso = "2025-09-04";
        System.out.println("Copia: salida " + copia.salida + " · Original: salida " + cusco.salida);
    }
}

// Ejercicio 10: RutaExpress - Factory Method (R1) + Observer (R3)
import java.util.*;
abstract class Transporte {
    final String nombre;
    final int dias;
    Transporte(String nombre, int dias) {
        this.nombre = nombre;
        this.dias = dias;
    }
}
class Camion extends Transporte {
    Camion() { super("Camión", 2); }
}
class Barco extends Transporte {
    Barco() { super("Barco", 15); }
}
class Avion extends Transporte {
    Avion() { super("Avión", 1); }
}
interface Interesado {
    void avisar(String estado);
}
class Canal implements Interesado {
    private final String nombre;
    Canal(String nombre) { this.nombre = nombre; }
    public void avisar(String estado) { System.out.println(nombre + " recibe: " + estado); }
}
abstract class Envio {
    private final String origen, destino;
    String ruta;
    private final List<Interesado> interesados = new ArrayList<>();
    Envio(String origen, String destino) {
        this.origen = origen;
        this.destino = destino;
    }
    abstract Transporte crearTransporte();
    String planificar() {
        Transporte transporte = crearTransporte();
        ruta = origen + " -> " + destino;
        String unidad = " días";
        if (transporte.dias == 1) {
            unidad = " día";
        }
        return transporte.nombre + ": " + transporte.dias + unidad;
    }
    void alta(Interesado i) { interesados.add(i); }
    void baja(Interesado i) { interesados.remove(i); }
    void cambiarEstado(String estado) {
        for (Interesado i : interesados) {
            i.avisar(estado);
        }
    }
}
class EnvioTerrestre extends Envio {
    EnvioTerrestre(String origen, String destino) { super(origen, destino); }
    Transporte crearTransporte() { return new Camion(); }
}
class EnvioMaritimo extends Envio {
    EnvioMaritimo(String origen, String destino) { super(origen, destino); }
    Transporte crearTransporte() { return new Barco(); }
}
class EnvioAereo extends Envio {
    EnvioAereo(String origen, String destino) { super(origen, destino); }
    Transporte crearTransporte() { return new Avion(); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Factory Method) ===");
        Envio terrestre = new EnvioTerrestre("Lima", "Cusco");
        Envio aereo = new EnvioAereo("Lima", "Arequipa");
        Envio maritimo = new EnvioMaritimo("Callao", "Valparaíso");
        System.out.println(terrestre.planificar() + " · " + aereo.planificar() + " · " + maritimo.planificar());
        System.out.println("Ruta asignada: " + terrestre.ruta);

        System.out.println("\n=== Caso 3 · Req. 3 (Observer) ===");
        Interesado remitente = new Canal("Remitente (correo)");
        Interesado destinatario = new Canal("Destinatario (SMS)");
        Interesado panel = new Canal("Panel de operaciones");
        terrestre.alta(remitente);
        terrestre.alta(destinatario);
        terrestre.alta(panel);
        terrestre.baja(destinatario);
        terrestre.cambiarEstado("entregado");
    }
}

// Ejercicio 11: Universidad Horizonte - Facade (R1) + Prototype (R3)
import java.util.*;
interface Prototipo<T> {
    T clonar();
}
class Seccion implements Prototipo<Seccion> {
    final String curso;
    String docente, aula;
    Seccion(String curso, String docente, String aula) {
        this.curso = curso;
        this.docente = docente;
        this.aula = aula;
    }
    public Seccion clonar() { return new Seccion(curso, docente, aula); }
}
class Horario implements Prototipo<Horario> {
    String ciclo;
    final List<Seccion> secciones = new ArrayList<>();
    Horario(String ciclo) { this.ciclo = ciclo; }
    public Horario clonar() {
        Horario copia = new Horario(ciclo);
        for (Seccion s : secciones) {
            copia.secciones.add(s.clonar());
        }
        return copia;
    }
}
class Tesoreria {
    void verificarDeudas(String estudiante) { System.out.println("  Tesorería: " + estudiante + " sin deudas"); }
}
class RegistroAcademico {
    void verificarPrerrequisitos(String estudiante) { System.out.println("  Registro académico: prerrequisitos de " + estudiante + " aprobados"); }
}
class Programacion {
    void verificarCupos(String estudiante) { System.out.println("  Programación: cupos y horarios para " + estudiante); }
    Horario nuevoCicloDesde(Horario anterior, String ciclo) {
        Horario nuevo = anterior.clonar();
        nuevo.ciclo = ciclo;
        return nuevo;
    }
}
class Pagos {
    void cobrar(String estudiante) { System.out.println("  Pagos: matrícula de " + estudiante + " cobrada"); }
}
class MatriculaFacade {
    private final Tesoreria tesoreria = new Tesoreria();
    private final RegistroAcademico registro = new RegistroAcademico();
    private final Programacion programacion;
    private final Pagos pagos = new Pagos();
    MatriculaFacade(Programacion programacion) { this.programacion = programacion; }
    String matricular(String estudiante) {
        tesoreria.verificarDeudas(estudiante);
        registro.verificarPrerrequisitos(estudiante);
        programacion.verificarCupos(estudiante);
        pagos.cobrar(estudiante);
        return "Matrícula confirmada";
    }
}
public class Main {
    public static void main(String[] args) {
        Programacion programacion = new Programacion();
        System.out.println("=== Caso 1 · Req. 1 (Facade) ===");
        MatriculaFacade portal = new MatriculaFacade(programacion);
        System.out.println(portal.matricular("Ana"));

        System.out.println("\n=== Caso 3 · Req. 3 (Prototype) ===");
        Horario h2025I = new Horario("2025-I");
        h2025I.secciones.add(new Seccion("Cálculo I", "Prof. Díaz", "A-101"));
        h2025I.secciones.add(new Seccion("Álgebra", "Prof. Rojas", "B-202"));
        Horario h2025II = programacion.nuevoCicloDesde(h2025I, "2025-II");
        h2025II.secciones.get(0).docente = "Prof. Vargas";
        System.out.println(h2025II.ciclo + ": Cálculo I con " + h2025II.secciones.get(0).docente);
        System.out.println(h2025I.ciclo + ": Cálculo I con " + h2025I.secciones.get(0).docente + " (no cambia)");
    }
}

// Ejercicio 12: FitZone - Decorator (R1) + Observer (R2)
import java.util.*;
interface Membresia {
    String descripcion();
    int costoMensual();
}
class MembresiaBase implements Membresia {
    public String descripcion() { return "Membresía"; }
    public int costoMensual() { return 30; }
}
abstract class ExtraMembresia implements Membresia {
    protected final Membresia membresia;
    ExtraMembresia(Membresia membresia) { this.membresia = membresia; }
}
class Piscina extends ExtraMembresia {
    Piscina(Membresia membresia) { super(membresia); }
    public String descripcion() { return membresia.descripcion() + " + Piscina"; }
    public int costoMensual() { return membresia.costoMensual() + 15; }
}
class Entrenador extends ExtraMembresia {
    Entrenador(Membresia membresia) { super(membresia); }
    public String descripcion() { return membresia.descripcion() + " + Entrenador personal"; }
    public int costoMensual() { return membresia.costoMensual() + 40; }
}
class Casillero extends ExtraMembresia {
    Casillero(Membresia membresia) { super(membresia); }
    public String descripcion() { return membresia.descripcion() + " + Casillero"; }
    public int costoMensual() { return membresia.costoMensual() + 5; }
}
class PaseClases extends ExtraMembresia {
    PaseClases(Membresia membresia) { super(membresia); }
    public String descripcion() { return membresia.descripcion() + " + Clases grupales"; }
    public int costoMensual() { return membresia.costoMensual() + 10; }
}
interface ObservadorClase {
    void actualizar(String aviso);
}
class Socio implements ObservadorClase {
    private final String nombre;
    private final Membresia membresia;
    Socio(String nombre, Membresia membresia) {
        this.nombre = nombre;
        this.membresia = membresia;
    }
    public void actualizar(String aviso) { System.out.println(nombre + " recibe: " + aviso); }
    String contrato() { return membresia.descripcion() + " -> $$" + membresia.costoMensual() + ".00/mes"; }
}
class ClaseGrupal {
    private final String nombre;
    private final List<ObservadorClase> inscritos = new ArrayList<>();
    ClaseGrupal(String nombre) { this.nombre = nombre; }
    void inscribir(ObservadorClase o) { inscritos.add(o); }
    void retirar(ObservadorClase o) { inscritos.remove(o); }
    void cambiarHorario(String hora) { avisar(nombre + " ahora es a las " + hora); }
    void cancelar() { avisar(nombre + " fue cancelada"); }
    private void avisar(String aviso) {
        for (ObservadorClase o : inscritos) {
            o.actualizar(aviso);
        }
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Decorator) ===");
        Membresia conExtras = new Casillero(new Piscina(new MembresiaBase()));
        Socio ana = new Socio("Ana", conExtras);
        System.out.println(ana.contrato());
        Membresia completa = new PaseClases(new Entrenador(new MembresiaBase()));
        System.out.println(new Socio("Marco", completa).contrato());

        System.out.println("\n=== Caso 2 · Req. 2 (Observer) ===");
        Socio luis = new Socio("Luis", new MembresiaBase());
        ClaseGrupal spinning = new ClaseGrupal("Spinning");
        spinning.inscribir(ana);
        spinning.inscribir(luis);
        spinning.retirar(luis);
        spinning.cambiarHorario("19:00");
        spinning.cancelar();
    }
}

// Ejercicio 13: Imperios en Guerra - Command (R1) + Memento (R4)
import java.util.*;
class Unidad {
    private final String nombre;
    Unidad(String nombre) { this.nombre = nombre; }
    void mover() { System.out.println(nombre + " se mueve"); }
    void atacar() { System.out.println(nombre + " ataca"); }
    void construir() { System.out.println(nombre + " construye"); }
}
interface Orden {
    void ejecutar();
}
class OrdenMover implements Orden {
    private final Unidad unidad;
    OrdenMover(Unidad unidad) { this.unidad = unidad; }
    public void ejecutar() { unidad.mover(); }
    public String toString() { return "mover"; }
}
class OrdenAtacar implements Orden {
    private final Unidad unidad;
    OrdenAtacar(Unidad unidad) { this.unidad = unidad; }
    public void ejecutar() { unidad.atacar(); }
    public String toString() { return "atacar"; }
}
class OrdenConstruir implements Orden {
    private final Unidad unidad;
    OrdenConstruir(Unidad unidad) { this.unidad = unidad; }
    public void ejecutar() { unidad.construir(); }
    public String toString() { return "construir"; }
}
class Guardado {
    final int turno;
    final int oro;
    final int unidades;
    Guardado(int turno, int oro, int unidades) {
        this.turno = turno;
        this.oro = oro;
        this.unidades = unidades;
    }
}
class Partida {
    int turno = 5;
    int oro = 300;
    int unidades = 12;
    List<Orden> cola = new ArrayList<Orden>();
    void ordenar(Orden orden) {
        cola.add(orden);
    }
    void deshacer() {
        if (cola.size() > 0) {
            cola.remove(cola.size() - 1);
        }
    }
    void avanzarTurno() {
        for (int i = 0; i < cola.size(); i++) {
            cola.get(i).ejecutar();
        }
        cola.clear();
        turno++;
    }
    Guardado guardar() {
        return new Guardado(turno, oro, unidades);
    }
    void cargar(Guardado g) {
        turno = g.turno;
        oro = g.oro;
        unidades = g.unidades;
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Command) ===");
        Partida partida1 = new Partida();
        Unidad soldado = new Unidad("Soldado");
        partida1.ordenar(new OrdenMover(soldado));
        partida1.ordenar(new OrdenAtacar(soldado));
        partida1.deshacer();
        System.out.println("En la cola: " + partida1.cola);
        partida1.avanzarTurno();
        System.out.println("\n=== Caso 4 · Req. 4 (Memento) ===");
        Partida partida = new Partida();
        Guardado guardado = partida.guardar();
        partida.oro = partida.oro - 200;
        partida.avanzarTurno();
        partida.cargar(guardado);
        System.out.println("Turno " + partida.turno + " con " + partida.oro + " de oro y " + partida.unidades + " unidades");
    }
}

// Ejercicio 14: DataReport - Proxy (R3) + Singleton (R4)
import java.util.*;
class Configuracion {
    static int lecturasArchivo = 0;
    private static final Configuracion instancia = new Configuracion();
    final String cadenaConexion;
    final String zonaHoraria;
    final String logo;
    private Configuracion() {
        lecturasArchivo++;
        cadenaConexion = "jdbc:postgresql://db/empresa";
        zonaHoraria = "America/Lima";
        logo = "logo.png";
    }
    static Configuracion getInstancia() {
        return instancia;
    }
}
interface FuenteDatos {
    String consultar(String consulta);
}
class BaseDatosVentas implements FuenteDatos {
    public String consultar(String consulta) {
        System.out.println("Consultando base de datos...");
        return consulta + " @ " + Configuracion.getInstancia().cadenaConexion;
    }
}
class FuenteDatosCache implements FuenteDatos {
    private final FuenteDatos real;
    private final Map<String, String> resultados = new HashMap<String, String>();
    private final Map<String, Long> horas = new HashMap<String, Long>();
    FuenteDatosCache(FuenteDatos real) {
        this.real = real;
    }
    public String consultar(String consulta) {
        if (resultados.containsKey(consulta)) {
            long minutos = (System.currentTimeMillis() - horas.get(consulta)) / 60000;
            if (minutos < 60) {
                System.out.println("Resultado desde caché");
                return resultados.get(consulta);
            }
        }
        String resultado = real.consultar(consulta);
        resultados.put(consulta, resultado);
        horas.put(consulta, System.currentTimeMillis());
        return resultado;
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 3 · Req. 3 (Proxy) ===");
        FuenteDatos fuente = new FuenteDatosCache(new BaseDatosVentas());
        System.out.println("Primera vez:");
        fuente.consultar("ventas 2025");
        System.out.println("Segunda vez:");
        fuente.consultar("ventas 2025");
        System.out.println("\n=== Caso 4 · Req. 4 (Singleton) ===");
        Configuracion moduloReportes = Configuracion.getInstancia();
        Configuracion moduloExportacion = Configuracion.getInstancia();
        System.out.println("¿Misma instancia? " + (moduloReportes == moduloExportacion) + " · Lecturas del archivo: " + Configuracion.lecturasArchivo);
        System.out.println("Zona horaria: " + moduloReportes.zonaHoraria + " · Logo: " + moduloExportacion.logo);
    }
}

// Ejercicio 15: CineMax - Flyweight (R1) + State (R2)
import java.util.*;
class TipoButaca {
    final int precio;
    final String descripcion;
    final String icono;
    TipoButaca(int precio, String descripcion, String icono) {
        this.precio = precio;
        this.descripcion = descripcion;
        this.icono = icono;
    }
}
class FabricaTiposButaca {
    private static final Map<String, TipoButaca> tipos = new HashMap<String, TipoButaca>();
    static TipoButaca obtener(String nombre) {
        if (!tipos.containsKey(nombre)) {
            if (nombre.equals("VIP")) {
                tipos.put(nombre, new TipoButaca(18, "Butaca VIP reclinable", "vip.svg"));
            } else if (nombre.equals("Accesible")) {
                tipos.put(nombre, new TipoButaca(10, "Butaca accesible con espacio libre", "accesible.svg"));
            } else {
                tipos.put(nombre, new TipoButaca(10, "Butaca estándar", "estandar.svg"));
            }
        }
        return tipos.get(nombre);
    }
    static int cantidad() {
        return tipos.size();
    }
}
interface EstadoButaca {
    String reservar(Butaca butaca);
    String pagar(Butaca butaca);
    String liberar(Butaca butaca);
}
class Libre implements EstadoButaca {
    public String reservar(Butaca butaca) {
        butaca.estado = new Reservada();
        return "Reservada";
    }
    public String pagar(Butaca butaca) {
        return "No se puede pagar: la butaca está libre";
    }
    public String liberar(Butaca butaca) {
        return "No se puede liberar: la butaca ya está libre";
    }
}
class Reservada implements EstadoButaca {
    public String reservar(Butaca butaca) {
        return "No se puede reservar: la butaca ya está reservada";
    }
    public String pagar(Butaca butaca) {
        butaca.estado = new Ocupada();
        return "Ocupada";
    }
    public String liberar(Butaca butaca) {
        butaca.estado = new Libre();
        return "Libre";
    }
}
class Ocupada implements EstadoButaca {
    public String reservar(Butaca butaca) {
        return "No se puede reservar: la butaca está ocupada";
    }
    public String pagar(Butaca butaca) {
        return "No se puede pagar: la butaca está ocupada";
    }
    public String liberar(Butaca butaca) {
        return "No se puede liberar: la butaca está ocupada";
    }
}
class Butaca {
    private final char fila;
    private final int numero;
    private final TipoButaca tipo;
    EstadoButaca estado = new Libre();
    Butaca(char fila, int numero, TipoButaca tipo) {
        this.fila = fila;
        this.numero = numero;
        this.tipo = tipo;
    }
    String reservar() { return estado.reservar(this); }
    String pagar() { return estado.pagar(this); }
    String liberar() { return estado.liberar(this); }
    String detalle() {
        return "Butaca " + fila + numero + ": " + tipo.descripcion + " ($$" + tipo.precio + ")";
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Flyweight) ===");
        List<Butaca> cadena = new ArrayList<Butaca>();
        Butaca f7 = null;
        Butaca f8 = null;
        for (int sala = 0; sala < 40; sala++) {
            for (char fila = 'A'; fila <= 'J'; fila++) {
                for (int numero = 1; numero <= 20; numero++) {
                    String nombreTipo = "Estándar";
                    if (sala % 4 == 3) {
                        nombreTipo = "VIP";
                    } else if (fila == 'J') {
                        nombreTipo = "Accesible";
                    }
                    Butaca butaca = new Butaca(fila, numero, FabricaTiposButaca.obtener(nombreTipo));
                    cadena.add(butaca);
                    if (sala == 0 && fila == 'F' && numero == 7) {
                        f7 = butaca;
                    }
                    if (sala == 0 && fila == 'F' && numero == 8) {
                        f8 = butaca;
                    }
                }
            }
        }
        System.out.println("Butacas de la cadena: " + cadena.size() + " · Objetos de tipo de butaca: " + FabricaTiposButaca.cantidad());
        System.out.println(f7.detalle());
        System.out.println("\n=== Caso 2 · Req. 2 (State) ===");
        System.out.println(f7.reservar() + " · " + f7.pagar());
        System.out.println(f7.reservar());
        System.out.println(f8.reservar() + " · " + f8.liberar());
    }
}

// Ejercicio 16: GuíaRuta - Adapter (R2) + Facade (R4)
interface ProveedorTrafico {
    double factorDemora(String via);
}
class TrafficNow {
    String colorDeVia(String via) {
        if (via.equals("Vía Expresa")) {
            return "rojo";
        } else if (via.contains("Arequipa")) {
            return "amarillo";
        } else {
            return "verde";
        }
    }
}
class TrafficNowAdapter implements ProveedorTrafico {
    private final TrafficNow servicio;
    TrafficNowAdapter(TrafficNow servicio) {
        this.servicio = servicio;
    }
    public double factorDemora(String via) {
        String color = servicio.colorDeVia(via);
        if (color.equals("rojo")) {
            return 2.0;
        } else if (color.equals("amarillo")) {
            return 1.5;
        } else {
            return 1.0;
        }
    }
}
class CalculadorRuta {
    private final ProveedorTrafico trafico;
    CalculadorRuta(ProveedorTrafico trafico) {
        this.trafico = trafico;
    }
    String ruta(String destino) {
        return "ruta por avenidas hacia " + destino;
    }
    double factor(String via) {
        return trafico.factorDemora(via);
    }
    double tiempoEnAuto(double km, String via) {
        return km / 40 * 60 * factor(via);
    }
}
class Geocodificador {
    String coordenadas(String direccion) {
        return "(-12.0823, -77.0348)";
    }
}
class InstruccionesVoz {
    String activar() {
        return "Instrucciones por voz activadas";
    }
}
class NavegacionFacade {
    private final Geocodificador geocodificador = new Geocodificador();
    private final CalculadorRuta calculador;
    private final InstruccionesVoz voz = new InstruccionesVoz();
    NavegacionFacade(CalculadorRuta calculador) {
        this.calculador = calculador;
    }
    void navegarA(String direccion) {
        String destino = geocodificador.coordenadas(direccion);
        System.out.println("1. Geocodificación: " + destino);
        System.out.println("2. Cálculo de ruta: " + calculador.ruta(destino));
        System.out.println("3. Consulta de tráfico: factor " + calculador.factor(direccion));
        System.out.println("4. " + voz.activar());
    }
}
public class Main {
    public static void main(String[] args) {
        CalculadorRuta calculador = new CalculadorRuta(new TrafficNowAdapter(new TrafficNow()));
        System.out.println("=== Caso 2 · Req. 2 (Adapter) ===");
        double factor = calculador.factor("Vía Expresa");
        long minutos = Math.round(calculador.tiempoEnAuto(10, "Vía Expresa"));
        System.out.println("Factor " + factor + " → tiempo estimado: " + minutos + " min");
        System.out.println("\n=== Caso 4 · Req. 4 (Facade) ===");
        NavegacionFacade pantalla = new NavegacionFacade(calculador);
        pantalla.navegarA("Av. Arequipa 1200");
    }
}

// Ejercicio 17: Conecta - Observer (R1) + Chain of Responsibility (R3)
import java.util.*;
interface Seguidor {
    void recibir(String texto);
}
abstract class Cuenta implements Seguidor {
    final String nombre;
    private final List<Seguidor> seguidores = new ArrayList<Seguidor>();
    private ControlModeracion moderacion;
    Cuenta(String nombre) {
        this.nombre = nombre;
    }
    void agregarSeguidor(Seguidor seguidor) {
        seguidores.add(seguidor);
    }
    void quitarSeguidor(Seguidor seguidor) {
        seguidores.remove(seguidor);
    }
    void setModeracion(ControlModeracion moderacion) {
        this.moderacion = moderacion;
    }
    String publicar(String texto) {
        if (moderacion != null) {
            String veredicto = moderacion.revisar(texto);
            if (veredicto != null) {
                return veredicto;
            }
        }
        for (int i = 0; i < seguidores.size(); i++) {
            seguidores.get(i).recibir(texto);
        }
        return "Publicado";
    }
}
class Persona extends Cuenta {
    Persona(String nombre) {
        super(nombre);
    }
    public void recibir(String texto) {
        System.out.println(nombre + " recibe: " + texto);
    }
}
class Pagina extends Cuenta {
    Pagina(String nombre) {
        super(nombre);
    }
    public void recibir(String texto) {
        System.out.println("Página " + nombre + " recibe: " + texto);
    }
}
class BotArchivo implements Seguidor {
    private final List<String> archivo = new ArrayList<String>();
    public void recibir(String texto) {
        archivo.add(texto);
        System.out.println("Bot de archivo guarda: " + texto + " (total " + archivo.size() + ")");
    }
}
abstract class ControlModeracion {
    private ControlModeracion siguiente;
    void setSiguiente(ControlModeracion siguiente) {
        this.siguiente = siguiente;
    }
    String revisar(String texto) {
        String resultado = evaluar(texto);
        if (resultado != null) {
            return resultado;
        }
        if (siguiente != null) {
            return siguiente.revisar(texto);
        }
        return null;
    }
    abstract String evaluar(String texto);
}
class FiltroSpam extends ControlModeracion {
    String evaluar(String texto) {
        if (texto.contains("gratis")) {
            return "Bloqueado por spam";
        }
        return null;
    }
}
class FiltroPalabrasProhibidas extends ControlModeracion {
    String evaluar(String texto) {
        if (texto.contains("estafa")) {
            return "Bloqueado por palabra prohibida";
        }
        return null;
    }
}
class RevisionEnlaces extends ControlModeracion {
    String evaluar(String texto) {
        if (texto.contains("http")) {
            return "Enviado a revisión humana";
        }
        return null;
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Observer) ===");
        Persona ana = new Persona("Ana");
        Persona beto = new Persona("Beto");
        Persona carla = new Persona("Carla");
        ana.agregarSeguidor(beto);
        ana.agregarSeguidor(carla);
        ana.quitarSeguidor(carla);
        ana.publicar("¡Hola a todos!");
        System.out.println("-- Ahora también la siguen una página y un bot --");
        ana.agregarSeguidor(new Pagina("Noticias"));
        ana.agregarSeguidor(new BotArchivo());
        ana.publicar("Segunda publicación");
        System.out.println("\n=== Caso 3 · Req. 3 (Chain of Responsibility) ===");
        ControlModeracion spam = new FiltroSpam();
        ControlModeracion palabras = new FiltroPalabrasProhibidas();
        ControlModeracion enlaces = new RevisionEnlaces();
        spam.setSiguiente(palabras);
        palabras.setSiguiente(enlaces);
        Persona dario = new Persona("Darío");
        dario.setModeracion(spam);
        System.out.println(dario.publicar("oferta gratis!!!"));
        System.out.println(dario.publicar("esto es una estafa"));
        System.out.println(dario.publicar("mira http://conecta.com/x"));
        System.out.println(dario.publicar("buen día a todos"));
    }
}

// Ejercicio 18: AutoMotriz Andes - Builder (R1) + Prototype (R3)
class Auto {
    final String modelo;
    String color;
    String aro;
    boolean techoSolar;
    boolean sonido;
    boolean paqueteSeguridad;
    Auto(String modelo) {
        this.modelo = modelo;
    }
    Auto clonar() {
        Auto copia = new Auto(modelo);
        copia.color = color;
        copia.aro = aro;
        copia.techoSolar = techoSolar;
        copia.sonido = sonido;
        copia.paqueteSeguridad = paqueteSeguridad;
        return copia;
    }
    public String toString() {
        String texto = modelo;
        if (color != null) {
            texto = texto + " " + color;
        }
        if (aro != null) {
            texto = texto + " · aros " + aro;
        }
        if (techoSolar) {
            texto = texto + " · techo solar";
        }
        if (sonido) {
            texto = texto + " · sonido";
        }
        if (paqueteSeguridad) {
            texto = texto + " · paquete de seguridad";
        }
        return texto;
    }
}
class AutoBuilder {
    private final Auto auto;
    AutoBuilder(String modelo) {
        auto = new Auto(modelo);
    }
    AutoBuilder color(String color) {
        auto.color = color;
        return this;
    }
    AutoBuilder aro(String aro) {
        auto.aro = aro;
        return this;
    }
    AutoBuilder techoSolar() {
        auto.techoSolar = true;
        return this;
    }
    AutoBuilder sonido() {
        auto.sonido = true;
        return this;
    }
    AutoBuilder paqueteSeguridad() {
        auto.paqueteSeguridad = true;
        return this;
    }
    Auto build() {
        return auto;
    }
}
class DirectorAutos {
    Auto basico() {
        return new AutoBuilder("Sedán").color("blanco").build();
    }
    Auto fullEquipo() {
        return new AutoBuilder("Sedán").color("negro").aro("aleación").techoSolar().sonido().paqueteSeguridad().build();
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Builder) ===");
        Auto sedan = new AutoBuilder("Sedán").color("rojo").techoSolar().build();
        DirectorAutos director = new DirectorAutos();
        System.out.println("Sedán configurado: " + sedan);
        System.out.println("Básico: " + director.basico());
        System.out.println("Full equipo: " + director.fullEquipo());
        System.out.println("\n=== Caso 3 · Req. 3 (Prototype) ===");
        Auto suv = new AutoBuilder("SUV").color("rojo").paqueteSeguridad().build();
        Auto[] flota = new Auto[3];
        for (int i = 0; i < flota.length; i++) {
            flota[i] = suv.clonar();
        }
        flota[0].color = "azul";
        System.out.println("Original: " + suv);
        for (int i = 0; i < flota.length; i++) {
            System.out.println("Copia " + (i + 1) + ": " + flota[i]);
        }
    }
}

// Ejercicio 19: PagoSeguro - Adapter (R1) + Command (R4)
import java.util.*;
class PayFlex {
    void cobrar(long centavos) {
        System.out.println("PayFlex: " + centavos + " centavos");
    }
}
class QuickCash {
    void pagar(double monto, String comercio) {
        long centavos = Math.round(monto * 100);
        String texto = (centavos / 100) + ".";
        if (centavos % 100 < 10) {
            texto = texto + "0";
        }
        texto = texto + (centavos % 100);
        System.out.println("QuickCash: " + texto + " (comercio " + comercio + ")");
    }
}
interface Proveedor {
    void cobrar(double monto, String moneda);
}
class PayFlexAdapter implements Proveedor {
    private PayFlex payFlex = new PayFlex();
    public void cobrar(double monto, String moneda) {
        long centavos = Math.round(monto * 100);
        payFlex.cobrar(centavos);
    }
}
class QuickCashAdapter implements Proveedor {
    private QuickCash quickCash = new QuickCash();
    public void cobrar(double monto, String moneda) {
        quickCash.pagar(monto, "0045");
    }
}
interface Operacion {
    void ejecutar();
    void revertir();
}
class Cobro implements Operacion {
    private Proveedor proveedor;
    private int monto;
    private String moneda;
    Cobro(Proveedor proveedor, int monto, String moneda) {
        this.proveedor = proveedor;
        this.monto = monto;
        this.moneda = moneda;
    }
    public void ejecutar() {
        if (monto <= 0) {
            throw new IllegalStateException("monto inválido");
        }
        proveedor.cobrar(monto, moneda);
    }
    public void revertir() {
        System.out.println("Revierte cobro de $$" + monto + " " + moneda);
    }
}
class Lote {
    private List<Operacion> cola = new ArrayList<>();
    void agregar(Operacion operacion) {
        cola.add(operacion);
    }
    void procesar() {
        List<Operacion> ejecutadas = new ArrayList<>();
        try {
            for (int i = 0; i < cola.size(); i++) {
                cola.get(i).ejecutar();
                ejecutadas.add(cola.get(i));
            }
        } catch (IllegalStateException e) {
            System.out.println("Falló la operación: " + e.getMessage());
            for (int i = ejecutadas.size() - 1; i >= 0; i--) {
                ejecutadas.get(i).revertir();
            }
        }
    }
}
public class Main {
    public static void main(String[] args) {
        Proveedor payFlex = new PayFlexAdapter();
        Proveedor quickCash = new QuickCashAdapter();
        System.out.println("=== Caso 1 · Req. 1 (Adapter) ===");
        payFlex.cobrar(25.50, "USD");
        quickCash.cobrar(25.50, "USD");
        System.out.println();
        System.out.println("=== Caso 4 · Req. 4 (Command) ===");
        Lote lote = new Lote();
        lote.agregar(new Cobro(payFlex, 10, "USD"));
        lote.agregar(new Cobro(quickCash, 20, "USD"));
        lote.agregar(new Cobro(payFlex, 0, "USD"));
        lote.procesar();
    }
}

// Ejercicio 20: BiblioRed - State (R2) + Observer (R3)
import java.util.*;
interface Estado {
    String prestar(Ejemplar ejemplar, String quien);
    String reservar(Ejemplar ejemplar, String quien);
    void devolver(Ejemplar ejemplar);
}
class Disponible implements Estado {
    public String prestar(Ejemplar ejemplar, String quien) {
        ejemplar.estado = new Prestado();
        return "Prestado";
    }
    public String reservar(Ejemplar ejemplar, String quien) {
        return "No se puede reservar: está disponible";
    }
    public void devolver(Ejemplar ejemplar) {
    }
}
class Prestado implements Estado {
    private String reservadoPara;
    public String prestar(Ejemplar ejemplar, String quien) {
        return "No disponible: ya está prestado";
    }
    public String reservar(Ejemplar ejemplar, String quien) {
        reservadoPara = quien;
        return "Reservado para " + quien;
    }
    public void devolver(Ejemplar ejemplar) {
        if (reservadoPara == null) {
            ejemplar.estado = new Disponible();
            ejemplar.avisar();
        } else {
            ejemplar.estado = new Reservado(reservadoPara);
        }
    }
}
class Reservado implements Estado {
    private String reservadoPara;
    Reservado(String reservadoPara) {
        this.reservadoPara = reservadoPara;
    }
    public String prestar(Ejemplar ejemplar, String quien) {
        if (!quien.equals(reservadoPara)) {
            return "No disponible: reservado para " + reservadoPara;
        }
        ejemplar.estado = new Prestado();
        return "Prestado";
    }
    public String reservar(Ejemplar ejemplar, String quien) {
        return "No se puede reservar: ya está reservado";
    }
    public void devolver(Ejemplar ejemplar) {
    }
}
class EnReparacion implements Estado {
    public String prestar(Ejemplar ejemplar, String quien) {
        return "No disponible: en reparación";
    }
    public String reservar(Ejemplar ejemplar, String quien) {
        return "No se puede reservar: en reparación";
    }
    public void devolver(Ejemplar ejemplar) {
    }
}
interface Observador {
    void actualizar(String titulo);
}
class Usuario implements Observador {
    private String nombre;
    private String canal;
    Usuario(String nombre, String canal) {
        this.nombre = nombre;
        this.canal = canal;
    }
    public void actualizar(String titulo) {
        System.out.println(nombre + " recibe por " + canal + ": \"" + titulo + "\" ya está disponible");
    }
}
class Ejemplar {
    String titulo;
    Estado estado = new Disponible();
    private List<Observador> observadores = new ArrayList<>();
    Ejemplar(String titulo) {
        this.titulo = titulo;
    }
    String prestar(String quien) {
        return estado.prestar(this, quien);
    }
    String reservar(String quien) {
        return estado.reservar(this, quien);
    }
    void devolver() {
        estado.devolver(this);
    }
    void enviarAReparacion() {
        estado = new EnReparacion();
    }
    void suscribir(Observador observador) {
        observadores.add(observador);
    }
    void retirar(Observador observador) {
        observadores.remove(observador);
    }
    void avisar() {
        for (int i = 0; i < observadores.size(); i++) {
            observadores.get(i).actualizar(titulo);
        }
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (State) ===");
        Ejemplar libro = new Ejemplar("Zorro");
        System.out.println(libro.prestar("Juan") + " · " + libro.reservar("Luis"));
        libro.devolver();
        System.out.println(libro.prestar("Ana"));
        Ejemplar revista = new Ejemplar("Mar");
        revista.enviarAReparacion();
        System.out.println(revista.prestar("Ana") + " · " + revista.reservar("Luis"));
        System.out.println();
        System.out.println("=== Caso 3 · Req. 3 (Observer) ===");
        Ejemplar biologia = new Ejemplar("Biología");
        biologia.prestar("Juan");
        Usuario ana = new Usuario("Ana", "correo");
        Usuario luis = new Usuario("Luis", "app");
        biologia.suscribir(ana);
        biologia.suscribir(luis);
        biologia.retirar(luis);
        biologia.devolver();
    }
}

