// Ejercicio 22: AulaVirtual - Composite (R1) + Iterator (R2)
import java.util.*;
interface Parte {
    int duracion();
    void reunirLecciones(List<Leccion> destino);
}
interface Iterador {
    boolean hasNext();
    Leccion next();
}
interface Agregado {
    Iterador iteradorEnOrden();
    Iterador iteradorPendientes();
}
class Leccion implements Parte {
    String nombre;
    boolean completada;
    private int minutos;
    Leccion(String nombre, int minutos) {
        this.nombre = nombre;
        this.minutos = minutos;
    }
    public int duracion() {
        return minutos;
    }
    public void reunirLecciones(List<Leccion> destino) {
        destino.add(this);
    }
}
class Modulo implements Parte, Agregado {
    private List<Parte> hijos = new ArrayList<>();
    void agregar(Parte hijo) {
        hijos.add(hijo);
    }
    public int duracion() {
        int total = 0;
        for (int i = 0; i < hijos.size(); i++) {
            total = total + hijos.get(i).duracion();
        }
        return total;
    }
    public void reunirLecciones(List<Leccion> destino) {
        for (int i = 0; i < hijos.size(); i++) {
            hijos.get(i).reunirLecciones(destino);
        }
    }
    public Iterador iteradorEnOrden() {
        return new IteradorEnOrden(this);
    }
    public Iterador iteradorPendientes() {
        return new IteradorPendientes(this);
    }
}
class IteradorEnOrden implements Iterador {
    private List<Leccion> lecciones = new ArrayList<>();
    private int posicion = 0;
    IteradorEnOrden(Modulo modulo) {
        modulo.reunirLecciones(lecciones);
    }
    public boolean hasNext() {
        return posicion < lecciones.size();
    }
    public Leccion next() {
        Leccion leccion = lecciones.get(posicion);
        posicion++;
        return leccion;
    }
}
class IteradorPendientes implements Iterador {
    private List<Leccion> pendientes = new ArrayList<>();
    private int posicion = 0;
    IteradorPendientes(Modulo modulo) {
        List<Leccion> todas = new ArrayList<>();
        modulo.reunirLecciones(todas);
        for (int i = 0; i < todas.size(); i++) {
            if (!todas.get(i).completada) {
                pendientes.add(todas.get(i));
            }
        }
    }
    public boolean hasNext() {
        return posicion < pendientes.size();
    }
    public Leccion next() {
        Leccion leccion = pendientes.get(posicion);
        posicion++;
        return leccion;
    }
}
public class Main {
    static String recorrer(Iterador iterador) {
        StringBuilder texto = new StringBuilder();
        while (iterador.hasNext()) {
            if (texto.length() > 0) {
                texto.append(", ");
            }
            texto.append(iterador.next().nombre);
        }
        return texto.toString();
    }
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Composite) ===");
        Modulo submodulo = new Modulo();
        submodulo.agregar(new Leccion("L3", 20));
        Modulo modulo = new Modulo();
        modulo.agregar(new Leccion("L1", 10));
        modulo.agregar(new Leccion("L2", 15));
        modulo.agregar(submodulo);
        System.out.println("Módulo: " + modulo.duracion() + " min · Submódulo: " + submodulo.duracion() + " min");
        System.out.println();
        System.out.println("=== Caso 2 · Req. 2 (Iterator) ===");
        Leccion l2 = new Leccion("L2", 10);
        l2.completada = true;
        Modulo curso = new Modulo();
        curso.agregar(new Leccion("L1", 10));
        curso.agregar(l2);
        curso.agregar(new Leccion("L3", 10));
        curso.agregar(new Leccion("L4", 10));
        System.out.println("En orden: " + recorrer(curso.iteradorEnOrden()));
        System.out.println("Pendientes: " + recorrer(curso.iteradorPendientes()));
    }
}

// Ejercicio 23: AeroAndes - Chain of Responsibility (R1) + Builder (R2)
import java.util.*;
class Maleta {
    int kg;
    int largo;
    int ancho;
    int alto;
    String contenido;
    Maleta(int kg, int largo, int ancho, int alto, String contenido) {
        this.kg = kg;
        this.largo = largo;
        this.ancho = ancho;
        this.alto = alto;
        this.contenido = contenido;
    }
}
abstract class ControlEquipaje {
    private ControlEquipaje siguiente;
    void setSiguiente(ControlEquipaje siguiente) {
        this.siguiente = siguiente;
    }
    String revisar(Maleta maleta) {
        String motivo = detectarProblema(maleta);
        if (motivo != null) {
            return "Rechazada: " + motivo;
        }
        if (siguiente != null) {
            return siguiente.revisar(maleta);
        }
        return "Aceptada";
    }
    abstract String detectarProblema(Maleta maleta);
}
class ControlPeso extends ControlEquipaje {
    String detectarProblema(Maleta maleta) {
        if (maleta.kg > 23) {
            return "excede 23 kg";
        }
        return null;
    }
}
class ControlDimensiones extends ControlEquipaje {
    String detectarProblema(Maleta maleta) {
        if (maleta.largo + maleta.ancho + maleta.alto > 158) {
            return "excede 158 cm";
        }
        return null;
    }
}
class ControlObjetosProhibidos extends ControlEquipaje {
    private List<String> prohibidos = new ArrayList<>();
    ControlObjetosProhibidos() {
        prohibidos.add("encendedor");
        prohibidos.add("explosivo");
    }
    String detectarProblema(Maleta maleta) {
        if (prohibidos.contains(maleta.contenido)) {
            return "objeto prohibido";
        }
        return null;
    }
}
class Itinerario {
    String pasajero;
    String vueloIda;
    String vueloRegreso;
    List<String> escalas = new ArrayList<>();
    String asiento;
    boolean equipajeExtra;
    String comidaEspecial;
    Itinerario(String pasajero, String vueloIda) {
        this.pasajero = pasajero;
        this.vueloIda = vueloIda;
    }
    void mostrar() {
        StringBuilder texto = new StringBuilder(pasajero + ": ida " + vueloIda);
        if (vueloRegreso != null) {
            texto.append(", regreso " + vueloRegreso);
        }
        for (int i = 0; i < escalas.size(); i++) {
            texto.append(", escala " + escalas.get(i));
        }
        if (asiento != null) {
            texto.append(", asiento " + asiento);
        }
        if (equipajeExtra) {
            texto.append(", equipaje extra");
        }
        if (comidaEspecial != null) {
            texto.append(", comida " + comidaEspecial);
        }
        System.out.println(texto);
    }
}
class ItinerarioBuilder {
    private Itinerario itinerario;
    private ControlEquipaje controles;
    ItinerarioBuilder(String pasajero, String vueloIda, ControlEquipaje controles) {
        this.itinerario = new Itinerario(pasajero, vueloIda);
        this.controles = controles;
    }
    ItinerarioBuilder regreso(String vuelo) {
        itinerario.vueloRegreso = vuelo;
        return this;
    }
    ItinerarioBuilder escala(String ciudad) {
        itinerario.escalas.add(ciudad);
        return this;
    }
    ItinerarioBuilder asiento(String codigo) {
        itinerario.asiento = codigo;
        return this;
    }
    ItinerarioBuilder equipajeExtra(Maleta maleta) {
        String resultado = controles.revisar(maleta);
        if (!resultado.equals("Aceptada")) {
            throw new IllegalArgumentException(resultado);
        }
        itinerario.equipajeExtra = true;
        return this;
    }
    ItinerarioBuilder comidaEspecial(String comida) {
        itinerario.comidaEspecial = comida;
        return this;
    }
    Itinerario construir() {
        return itinerario;
    }
}
class PlantillasItinerario {
    Itinerario soloIdaEconomico(String pasajero, String vueloIda, ControlEquipaje controles) {
        ItinerarioBuilder builder = new ItinerarioBuilder(pasajero, vueloIda, controles);
        return builder.construir();
    }
}
public class Main {
    public static void main(String[] args) {
        ControlEquipaje peso = new ControlPeso();
        ControlEquipaje dimensiones = new ControlDimensiones();
        ControlEquipaje prohibidos = new ControlObjetosProhibidos();
        peso.setSiguiente(dimensiones);
        dimensiones.setSiguiente(prohibidos);
        System.out.println("=== Caso 1 · Req. 1 (Chain of Responsibility) ===");
        System.out.println(peso.revisar(new Maleta(25, 60, 40, 30, "ropa")));
        System.out.println(peso.revisar(new Maleta(20, 70, 50, 50, "ropa")));
        System.out.println(peso.revisar(new Maleta(20, 60, 50, 40, "encendedor")));
        System.out.println(peso.revisar(new Maleta(18, 60, 40, 40, "ropa")));
        System.out.println();
        System.out.println("=== Caso 2 · Req. 2 (Builder) ===");
        ItinerarioBuilder builder = new ItinerarioBuilder("Ana Pérez", "Lima–Cusco AA201", peso);
        builder.regreso("Cusco–Lima AA202");
        builder.asiento("12A");
        builder.construir().mostrar();
        PlantillasItinerario plantillas = new PlantillasItinerario();
        plantillas.soloIdaEconomico("Luis Rojas", "Lima–Piura AA310", peso).mostrar();
        ItinerarioBuilder otro = new ItinerarioBuilder("Marta Díaz", "Lima–Arequipa AA120", peso);
        otro.escala("Cusco");
        otro.comidaEspecial("vegetariana");
        otro.equipajeExtra(new Maleta(18, 60, 40, 40, "ropa"));
        otro.construir().mostrar();
        try {
            otro.equipajeExtra(new Maleta(30, 60, 40, 40, "ropa"));
        } catch (IllegalArgumentException e) {
            System.out.println("Equipaje extra " + e.getMessage());
        }
    }
}

// Ejercicio 24: PixelArt - Composite (R1) + Prototype (R2)
import java.util.*;
interface Figura {
    void mover(int dx, int dy);
    void setColor(String color);
    Figura clonar();
    String describir();
    String detalle();
}
class Circulo implements Figura {
    private int x;
    private int y;
    private String color = "negro";
    private int grosor;
    Circulo(int x, int y, int grosor) {
        this.x = x;
        this.y = y;
        this.grosor = grosor;
    }
    public void mover(int dx, int dy) {
        x = x + dx;
        y = y + dy;
    }
    public void setColor(String color) {
        this.color = color;
    }
    public Figura clonar() {
        Circulo copia = new Circulo(x, y, grosor);
        copia.color = color;
        return copia;
    }
    public String describir() {
        return "Círculo en (" + x + ", " + y + ")";
    }
    public String detalle() {
        return describir() + " [" + color + ", grosor " + grosor + "]";
    }
}
class Rectangulo implements Figura {
    private int x;
    private int y;
    private String color = "negro";
    private int grosor;
    Rectangulo(int x, int y, int grosor) {
        this.x = x;
        this.y = y;
        this.grosor = grosor;
    }
    public void mover(int dx, int dy) {
        x = x + dx;
        y = y + dy;
    }
    public void setColor(String color) {
        this.color = color;
    }
    public Figura clonar() {
        Rectangulo copia = new Rectangulo(x, y, grosor);
        copia.color = color;
        return copia;
    }
    public String describir() {
        return "Rectángulo en (" + x + ", " + y + ")";
    }
    public String detalle() {
        return describir() + " [" + color + ", grosor " + grosor + "]";
    }
}
class Linea implements Figura {
    private int x1;
    private int y1;
    private int x2;
    private int y2;
    private String color = "negro";
    private int grosor;
    Linea(int x1, int y1, int x2, int y2, int grosor) {
        this.x1 = x1;
        this.y1 = y1;
        this.x2 = x2;
        this.y2 = y2;
        this.grosor = grosor;
    }
    public void mover(int dx, int dy) {
        x1 = x1 + dx;
        y1 = y1 + dy;
        x2 = x2 + dx;
        y2 = y2 + dy;
    }
    public void setColor(String color) {
        this.color = color;
    }
    public Figura clonar() {
        Linea copia = new Linea(x1, y1, x2, y2, grosor);
        copia.color = color;
        return copia;
    }
    public String describir() {
        return "Línea de (" + x1 + ", " + y1 + ") a (" + x2 + ", " + y2 + ")";
    }
    public String detalle() {
        return describir() + " [" + color + ", grosor " + grosor + "]";
    }
}
class Grupo implements Figura {
    private List<Figura> figuras = new ArrayList<>();
    void agregar(Figura figura) {
        figuras.add(figura);
    }
    public void mover(int dx, int dy) {
        for (int i = 0; i < figuras.size(); i++) {
            figuras.get(i).mover(dx, dy);
        }
    }
    public void setColor(String color) {
        for (int i = 0; i < figuras.size(); i++) {
            figuras.get(i).setColor(color);
        }
    }
    public Figura clonar() {
        Grupo copia = new Grupo();
        for (int i = 0; i < figuras.size(); i++) {
            copia.agregar(figuras.get(i).clonar());
        }
        return copia;
    }
    public String describir() {
        String texto = "";
        for (int i = 0; i < figuras.size(); i++) {
            if (i > 0) {
                texto = texto + " · ";
            }
            texto = texto + figuras.get(i).describir();
        }
        return texto;
    }
    public String detalle() {
        String texto = "";
        for (int i = 0; i < figuras.size(); i++) {
            if (i > 0) {
                texto = texto + " · ";
            }
            texto = texto + figuras.get(i).detalle();
        }
        return texto;
    }
}
class Editor {
    Figura duplicar(Figura figura) {
        Figura copia = figura.clonar();
        copia.mover(10, 10);
        return copia;
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Composite) ===");
        Grupo grupo = new Grupo();
        grupo.agregar(new Circulo(0, 0, 1));
        grupo.agregar(new Rectangulo(5, 5, 1));
        grupo.mover(10, 10);
        System.out.println(grupo.describir());
        Grupo marco = new Grupo();
        marco.agregar(new Linea(0, 0, 4, 0, 1));
        marco.agregar(grupo);
        marco.mover(1, 1);
        System.out.println(marco.describir());
        System.out.println();
        System.out.println("=== Caso 2 · Req. 2 (Prototype) ===");
        Grupo original = new Grupo();
        original.agregar(new Circulo(0, 0, 2));
        original.agregar(new Rectangulo(5, 5, 2));
        Editor editor = new Editor();
        Figura copia = editor.duplicar(original);
        copia.setColor("rojo");
        System.out.println("Copia:    " + copia.detalle());
        System.out.println("Original: " + original.detalle());
    }
}

// Ejercicio 25: AvisaYa - Decorator (R2) + Flyweight (R4)
import java.util.*;
interface Procesable { String procesar(); }
class Texto implements Procesable {
    private final String contenido;
    Texto(String contenido) { this.contenido = contenido; }
    public String procesar() { return contenido; }
    String enviarA(String nombre, String destino) {
        return contenido + " -> " + nombre + " <" + destino + ">";
    }
}
class FabricaTextos {
    final HashMap<String, Texto> textos = new HashMap<String, Texto>();
    Texto obtener(String contenido) {
        if (!textos.containsKey(contenido)) {
            textos.put(contenido, new Texto(contenido));
        }
        return textos.get(contenido);
    }
}
abstract class Proceso implements Procesable {
    protected Procesable base;
    Proceso(Procesable base) { this.base = base; }
}
class Compresion extends Proceso {
    Compresion(Procesable base) { super(base); }
    public String procesar() { return "comprimido(" + base.procesar() + ")"; }
}
class Cifrado extends Proceso {
    Cifrado(Procesable base) { super(base); }
    public String procesar() { return "cifrado(" + base.procesar() + ")"; }
}
class Firma extends Proceso {
    Firma(Procesable base) { super(base); }
    public String procesar() { return "firmado(" + base.procesar() + ")"; }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (Decorator) ===");
        Procesable p = new Cifrado(new Compresion(new Texto("hola")));
        System.out.println(p.procesar());
        Procesable otro = new Firma(new Cifrado(new Texto("hola")));
        System.out.println(otro.procesar());
        System.out.println();
        System.out.println("=== Caso 4 · Req. 4 (Flyweight) ===");
        FabricaTextos fabrica = new FabricaTextos();
        Texto primero = fabrica.obtener("2x1 en todo");
        int compartidos = 0;
        for (int i = 0; i < 1000000; i++) {
            if (fabrica.obtener("2x1 en todo") == primero) {
                compartidos++;
            }
        }
        System.out.println(compartidos + " envíos comparten " + fabrica.textos.size() + " objeto de contenido");
        System.out.println(primero.enviarA("Ana", "ana@mail.com"));
        System.out.println(primero.enviarA("Luis", "luis@mail.com"));
    }
}

// Ejercicio 26: CajeroNet - Chain of Responsibility (R2) + Facade (R3)
abstract class ManejadorBilletes {
    protected ManejadorBilletes siguiente;
    void setSiguiente(ManejadorBilletes siguiente) { this.siguiente = siguiente; }
    abstract String entregar(int monto);
}
class BandejaBilletes extends ManejadorBilletes {
    private final int valor;
    BandejaBilletes(int valor) { this.valor = valor; }
    String entregar(int monto) {
        int cantidad = monto / valor;
        int resto = monto % valor;
        String parte = "";
        if (cantidad > 0) {
            parte = cantidad + " × " + valor;
        }
        if (resto == 0) {
            return parte;
        }
        if (siguiente == null) {
            return null;
        }
        String demas = siguiente.entregar(resto);
        if (demas == null) {
            return null;
        }
        if (parte.equals("")) {
            return demas;
        }
        return parte + ", " + demas;
    }
}
class ServidorBanco {
    private int saldo;
    ServidorBanco(int saldo) { this.saldo = saldo; }
    int consultarSaldo() { return saldo; }
    void debitar(int monto) { saldo = saldo - monto; }
}
class Impresora {
    void imprimir(String texto) { System.out.println("Comprobante: " + texto); }
}
class RetiroFacade {
    private final ServidorBanco banco;
    private final ManejadorBilletes bandejas;
    private final Impresora impresora = new Impresora();
    RetiroFacade(ServidorBanco banco, ManejadorBilletes bandejas) {
        this.banco = banco;
        this.bandejas = bandejas;
    }
    String retirar(int monto) {
        if (banco.consultarSaldo() < monto) {
            return "Saldo insuficiente";
        }
        String billetes = bandejas.entregar(monto);
        if (billetes == null) {
            return "Monto no válido";
        }
        banco.debitar(monto);
        impresora.imprimir("retiro $$" + monto + " (" + billetes + ")");
        return "Saldo final: $$" + banco.consultarSaldo();
    }
}
public class Main {
    public static void main(String[] args) {
        ManejadorBilletes b100 = new BandejaBilletes(100);
        ManejadorBilletes b50 = new BandejaBilletes(50);
        ManejadorBilletes b20 = new BandejaBilletes(20);
        ManejadorBilletes b10 = new BandejaBilletes(10);
        b100.setSiguiente(b50);
        b50.setSiguiente(b20);
        b20.setSiguiente(b10);
        System.out.println("=== Caso 2 · Req. 2 (Chain of Responsibility) ===");
        String r1 = b100.entregar(380);
        System.out.println(r1);
        String r2 = b100.entregar(15);
        if (r2 == null) {
            System.out.println("Monto no válido");
        } else {
            System.out.println(r2);
        }
        System.out.println();
        System.out.println("=== Caso 3 · Req. 3 (Facade) ===");
        RetiroFacade cajero = new RetiroFacade(new ServidorBanco(1000), b100);
        System.out.println(cajero.retirar(200));
        System.out.println(cajero.retirar(15));
        System.out.println(cajero.retirar(5000));
    }
}

// Ejercicio 27: CalcuPro - Composite (R2) + Visitor (R3)
interface Expresion {
    int evaluar();
    void aceptar(Visitante v);
}
class Numero implements Expresion {
    final int valor;
    Numero(int valor) { this.valor = valor; }
    public int evaluar() { return valor; }
    public void aceptar(Visitante v) { v.visitar(this); }
}
class Operacion implements Expresion {
    final char simbolo;
    final Expresion izq;
    final Expresion der;
    Operacion(char simbolo, Expresion izq, Expresion der) {
        this.simbolo = simbolo;
        this.izq = izq;
        this.der = der;
    }
    public int evaluar() {
        int a = izq.evaluar();
        int b = der.evaluar();
        if (simbolo == '+') {
            return a + b;
        }
        if (simbolo == '-') {
            return a - b;
        }
        if (simbolo == '×') {
            return a * b;
        }
        return a / b;
    }
    public void aceptar(Visitante v) { v.visitar(this); }
}
interface Visitante {
    void visitar(Numero n);
    void visitar(Operacion o);
}
class Normal implements Visitante {
    String texto = "";
    public void visitar(Numero n) { texto = texto + n.valor; }
    public void visitar(Operacion o) {
        texto = texto + "(";
        o.izq.aceptar(this);
        texto = texto + " " + o.simbolo + " ";
        o.der.aceptar(this);
        texto = texto + ")";
    }
}
class Polaca implements Visitante {
    String texto = "";
    public void visitar(Numero n) { texto = texto + n.valor + " "; }
    public void visitar(Operacion o) {
        texto = texto + o.simbolo + " ";
        o.izq.aceptar(this);
        o.der.aceptar(this);
    }
}
class Contador implements Visitante {
    int total = 0;
    public void visitar(Numero n) { }
    public void visitar(Operacion o) {
        total++;
        o.izq.aceptar(this);
        o.der.aceptar(this);
    }
}
public class Main {
    public static void main(String[] args) {
        Expresion suma = new Operacion('+', new Numero(2), new Numero(3));
        Expresion e = new Operacion('×', suma, new Numero(4));
        System.out.println("=== Caso 2 · Req. 2 (Composite) ===");
        System.out.println(e.evaluar() + " · " + new Numero(7).evaluar());
        Expresion otra = new Operacion('/', new Operacion('-', new Numero(10), new Numero(4)), new Numero(2));
        System.out.println("(10 - 4) / 2 = " + otra.evaluar());
        System.out.println();
        System.out.println("=== Caso 3 · Req. 3 (Visitor) ===");
        Normal normal = new Normal();
        Polaca polaca = new Polaca();
        Contador contador = new Contador();
        e.aceptar(normal);
        e.aceptar(polaca);
        e.aceptar(contador);
        System.out.println(normal.texto + " · " + polaca.texto.trim() + " · " + contador.total + " operaciones");
    }
}

// Ejercicio 28: SeguroTotal - Template Method (R1) + Visitor (R4)
interface Operacion {
    void visitar(Auto a);
    void visitar(Vida v);
    void visitar(Hogar h);
}
class ReservaTecnica implements Operacion {
    String resultado = "";
    public void visitar(Auto a) { resultado = Seguro.dinero(a.prima() * 0.10); }
    public void visitar(Vida v) { resultado = Seguro.dinero(v.prima() * 0.25); }
    public void visitar(Hogar h) { resultado = Seguro.dinero(h.prima() * 0.15); }
}
class ResumenRegulador implements Operacion {
    String resultado = "";
    public void visitar(Auto a) {
        resultado = "Auto, conductor de " + a.edad + " años, prima " + Seguro.dinero(a.prima());
    }
    public void visitar(Vida v) {
        resultado = "Vida, asegurado de " + v.edad + " años, prima " + Seguro.dinero(v.prima());
    }
    public void visitar(Hogar h) {
        String zona = "zona no sísmica";
        if (h.sismica) {
            zona = "zona sísmica";
        }
        resultado = "Hogar en " + zona + ", prima " + Seguro.dinero(h.prima());
    }
}
abstract class Seguro {
    double tarifa;
    Seguro(double tarifa) { this.tarifa = tarifa; }
    double prima() {
        double conRiesgo = tarifa * factorRiesgo();
        double conGastos = conRiesgo + 20;
        return conGastos * 1.18;
    }
    abstract double factorRiesgo();
    abstract void aceptar(Operacion o);
    static String dinero(double monto) {
        int centavos = (int) Math.round(monto * 100);
        int resto = centavos % 100;
        String ceros = "";
        if (resto < 10) {
            ceros = "0";
        }
        return "$$" + (centavos / 100) + "." + ceros + resto;
    }
}
class Auto extends Seguro {
    int edad;
    Auto(double tarifa, int edad) {
        super(tarifa);
        this.edad = edad;
    }
    double factorRiesgo() {
        if (edad < 25) {
            return 1.5;
        }
        return 1.0;
    }
    void aceptar(Operacion o) { o.visitar(this); }
}
class Vida extends Seguro {
    int edad;
    Vida(double tarifa, int edad) {
        super(tarifa);
        this.edad = edad;
    }
    double factorRiesgo() {
        int anios = 0;
        if (edad > 40) {
            anios = edad - 40;
        }
        return 1.0 + 0.02 * anios;
    }
    void aceptar(Operacion o) { o.visitar(this); }
}
class Hogar extends Seguro {
    boolean sismica;
    Hogar(double tarifa, boolean sismica) {
        super(tarifa);
        this.sismica = sismica;
    }
    double factorRiesgo() {
        if (sismica) {
            return 1.2;
        }
        return 1.0;
    }
    void aceptar(Operacion o) { o.visitar(this); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Template Method) ===");
        Seguro auto = new Auto(200, 22);
        Seguro hogar = new Hogar(100, true);
        System.out.println(Seguro.dinero(auto.prima()) + " · " + Seguro.dinero(hogar.prima()));
        Seguro vida = new Vida(150, 50);
        System.out.println("Vida de 50 años, tarifa $$150: " + Seguro.dinero(vida.prima()));
        System.out.println();
        System.out.println("=== Caso 4 · Req. 4 (Visitor) ===");
        double tarifa = 1000 / 1.18 - 20;
        Seguro[] polizas = { new Auto(tarifa, 30), new Vida(tarifa, 40), new Hogar(tarifa, false) };
        ReservaTecnica reserva = new ReservaTecnica();
        String linea = "";
        for (int i = 0; i < polizas.length; i++) {
            polizas[i].aceptar(reserva);
            if (i > 0) {
                linea = linea + " · ";
            }
            linea = linea + reserva.resultado;
        }
        System.out.println(linea);
        ResumenRegulador resumen = new ResumenRegulador();
        for (int i = 0; i < polizas.length; i++) {
            polizas[i].aceptar(resumen);
            System.out.println(resumen.resultado);
        }
    }
}

// Ejercicio 29: Súper Salto - Memento (R3) + Flyweight (R4)
import java.util.*;
class Personaje {
    private String forma;
    private int monedas;
    private int posicion;
    Personaje(String forma, int monedas, int posicion) {
        this.forma = forma;
        this.monedas = monedas;
        this.posicion = posicion;
    }
    void juntar(int cantidad) { monedas = monedas + cantidad; }
    void avanzar(int distancia) { posicion = posicion + distancia; }
    String estado() {
        return monedas + " monedas, en forma " + forma + ", en la posición " + posicion;
    }
    PuntoControl guardar() { return new PuntoControl(posicion, monedas, forma); }
    void restaurar(PuntoControl punto) {
        posicion = punto.posicion;
        monedas = punto.monedas;
        forma = punto.forma;
    }
}
class PuntoControl {
    final int posicion;
    final int monedas;
    final String forma;
    PuntoControl(int posicion, int monedas, String forma) {
        this.posicion = posicion;
        this.monedas = monedas;
        this.forma = forma;
    }
}
class TipoElemento {
    private final String imagen;
    private final String animacion;
    TipoElemento(String nombre) {
        imagen = nombre + ".png";
        animacion = nombre + ".gif";
    }
    String dibujar(int x, int y) { return imagen + " (" + animacion + ") en " + x + "," + y; }
}
class FabricaTipos {
    private final HashMap<String, TipoElemento> tipos = new HashMap<String, TipoElemento>();
    TipoElemento obtener(String nombre) {
        if (!tipos.containsKey(nombre)) {
            tipos.put(nombre, new TipoElemento(nombre));
        }
        return tipos.get(nombre);
    }
    int cantidad() { return tipos.size(); }
}
class ElementoNivel {
    private final int x;
    private final int y;
    private final TipoElemento tipo;
    ElementoNivel(int x, int y, TipoElemento tipo) {
        this.x = x;
        this.y = y;
        this.tipo = tipo;
    }
    String dibujar() { return tipo.dibujar(x, y); }
}
class Nivel {
    private final ArrayList<ElementoNivel> elementos = new ArrayList<ElementoNivel>();
    private final FabricaTipos fabrica = new FabricaTipos();
    private PuntoControl bandera;
    void colocar(int x, int y, String tipo) {
        elementos.add(new ElementoNivel(x, y, fabrica.obtener(tipo)));
    }
    int cantidadElementos() { return elementos.size(); }
    int cantidadTipos() { return fabrica.cantidad(); }
    String dibujar(int indice) { return elementos.get(indice).dibujar(); }
    void tocarBandera(Personaje personaje) { bandera = personaje.guardar(); }
    void caerAlPrecipicio(Personaje personaje) { personaje.restaurar(bandera); }
}
public class Main {
    public static void main(String[] args) {
        Nivel nivel = new Nivel();
        System.out.println("=== Caso 3 · Req. 3 (Memento) ===");
        Personaje p = new Personaje("Grande", 12, 40);
        nivel.tocarBandera(p);
        p.juntar(5);
        p.avanzar(35);
        System.out.println("Antes de caer: " + p.estado());
        nivel.caerAlPrecipicio(p);
        System.out.println("Vuelve a la bandera con " + p.estado());
        System.out.println();
        System.out.println("=== Caso 4 · Req. 4 (Flyweight) ===");
        String[] tipos = { "moneda", "bloque de ladrillo", "bloque sorpresa" };
        for (int i = 0; i < 5000; i++) {
            nivel.colocar(i, 10, tipos[i % 3]);
        }
        System.out.println(nivel.cantidadElementos() + " elementos en el nivel");
        System.out.println("Solo existen " + nivel.cantidadTipos() + " objetos de tipo de elemento");
        System.out.println(nivel.dibujar(0));
        System.out.println(nivel.dibujar(4999));
    }
}

// Ejercicio 30: FarmaVida - Adapter (R1) + Facade (R4)
import java.util.*;
interface Catalogo {
    double precio(String codigo);
    int stock(String codigo);
}
class MediDistrib {
    private final HashMap<String, Integer> precios = new HashMap<String, Integer>();
    private final HashMap<String, Integer> existencias = new HashMap<String, Integer>();
    MediDistrib() {
        precios.put("MD-778", 1250);
        precios.put("MD-101", 300);
        existencias.put("MD-778", 40);
        existencias.put("MD-101", 25);
    }
    int precioEnCentimos(String codigoMD) { return precios.get(codigoMD); }
    int existencias(String codigoMD) { return existencias.get(codigoMD); }
}
class MediDistribAdapter implements Catalogo {
    private final MediDistrib mayorista = new MediDistrib();
    private final HashMap<String, String> codigos = new HashMap<String, String>();
    MediDistribAdapter() {
        codigos.put("AMOX-500", "MD-778");
        codigos.put("PARA-500", "MD-101");
    }
    public double precio(String codigo) {
        int centimos = mayorista.precioEnCentimos(codigos.get(codigo));
        return centimos / 100.0;
    }
    public int stock(String codigo) { return mayorista.existencias(codigos.get(codigo)); }
}
class ValidadorReceta {
    void validar() { System.out.println("0. Receta validada"); }
}
class Inventario {
    private int stock = 10;
    boolean hayStock() {
        System.out.println("1. Stock verificado");
        return stock > 0;
    }
    void actualizar() {
        stock = stock - 1;
        System.out.println("5. Inventario actualizado");
    }
}
class Caja {
    double descontar(double monto) {
        System.out.println("2. Descuento aplicado");
        return monto;
    }
    void cobrar(double monto) { System.out.println("3. Cobrado " + soles(monto)); }
    void emitirBoleta() { System.out.println("4. Boleta emitida"); }
    static String soles(double monto) {
        int centimos = (int) Math.round(monto * 100);
        int resto = centimos % 100;
        String cero = "";
        if (resto < 10) {
            cero = "0";
        }
        return "S/ " + (centimos / 100) + "." + cero + resto;
    }
}
class Farmacia {
    private final Catalogo catalogo;
    private final ValidadorReceta validador = new ValidadorReceta();
    private final Inventario inventario = new Inventario();
    private final Caja caja = new Caja();
    Farmacia(Catalogo catalogo) { this.catalogo = catalogo; }
    void vender(String codigo, boolean conReceta) {
        if (conReceta) {
            validador.validar();
        }
        if (!inventario.hayStock()) {
            System.out.println("Sin stock");
            return;
        }
        double precio = catalogo.precio(codigo);
        double total = caja.descontar(precio);
        caja.cobrar(total);
        caja.emitirBoleta();
        inventario.actualizar();
    }
}
public class Main {
    public static void main(String[] args) {
        Catalogo mayorista = new MediDistribAdapter();
        System.out.println("=== Caso 1 · Req. 1 (Adapter) ===");
        System.out.println("AMOX-500: " + Caja.soles(mayorista.precio("AMOX-500")));
        System.out.println("Stock en el mayorista: " + mayorista.stock("AMOX-500"));
        System.out.println();
        System.out.println("=== Caso 4 · Req. 4 (Facade) ===");
        Farmacia farmacia = new Farmacia(mayorista);
        farmacia.vender("PARA-500", false);
    }
}

// Ejercicio 31: Aventura Park - Singleton (R3) + Iterator (R4)
import java.util.*;
class ContadorAforo {
    static final int MAXIMO = 5000;
    private static final ContadorAforo INSTANCIA = new ContadorAforo();
    int dentro;
    private ContadorAforo() { dentro = 0; }
    public static ContadorAforo getInstancia() { return INSTANCIA; }
    public boolean ingresar() {
        if (dentro >= MAXIMO) {
            return false;
        }
        dentro++;
        return true;
    }
    public void salir() { dentro--; }
}
class Puerta {
    public String ingresar() {
        if (ContadorAforo.getInstancia().ingresar()) {
            return "Ingreso permitido";
        }
        return "Ingreso denegado: aforo completo";
    }
    public void salir() { ContadorAforo.getInstancia().salir(); }
}
class Atraccion {
    String nombre;
    int metros, espera;
    boolean apta;
    Atraccion(String nombre, int metros, boolean apta, int espera) {
        this.nombre = nombre;
        this.metros = metros;
        this.apta = apta;
        this.espera = espera;
    }
}
interface IteradorAtracciones {
    boolean tieneSiguiente();
    Atraccion siguiente();
}
class IteradorCercania implements IteradorAtracciones {
    private ArrayList<Atraccion> orden = new ArrayList<>();
    private int pos = 0;
    IteradorCercania(ArrayList<Atraccion> atracciones) {
        orden.addAll(atracciones);
        for (int i = 0; i < orden.size(); i++) {
            for (int j = i + 1; j < orden.size(); j++) {
                if (orden.get(j).metros < orden.get(i).metros) {
                    Atraccion temp = orden.get(i);
                    orden.set(i, orden.get(j));
                    orden.set(j, temp);
                }
            }
        }
    }
    public boolean tieneSiguiente() { return pos < orden.size(); }
    public Atraccion siguiente() {
        pos++;
        return orden.get(pos - 1);
    }
}
class IteradorAptasNinos extends IteradorCercania {
    IteradorAptasNinos(ArrayList<Atraccion> atracciones) { super(soloAptas(atracciones)); }
    private static ArrayList<Atraccion> soloAptas(ArrayList<Atraccion> atracciones) {
        ArrayList<Atraccion> aptas = new ArrayList<>();
        for (Atraccion a : atracciones) {
            if (a.apta) {
                aptas.add(a);
            }
        }
        return aptas;
    }
}
class IteradorMenorEspera implements IteradorAtracciones {
    private ArrayList<Atraccion> orden = new ArrayList<>();
    private int pos = 0;
    IteradorMenorEspera(ArrayList<Atraccion> atracciones) {
        orden.addAll(atracciones);
        for (int i = 0; i < orden.size(); i++) {
            for (int j = i + 1; j < orden.size(); j++) {
                if (orden.get(j).espera < orden.get(i).espera) {
                    Atraccion temp = orden.get(i);
                    orden.set(i, orden.get(j));
                    orden.set(j, temp);
                }
            }
        }
    }
    public boolean tieneSiguiente() { return pos < orden.size(); }
    public Atraccion siguiente() {
        pos++;
        return orden.get(pos - 1);
    }
}
class Parque {
    private ArrayList<Atraccion> atracciones = new ArrayList<>();
    public void agregar(Atraccion a) { atracciones.add(a); }
    public IteradorAtracciones porCercania() { return new IteradorCercania(atracciones); }
    public IteradorAtracciones aptasNinos() { return new IteradorAptasNinos(atracciones); }
    public IteradorAtracciones porEspera() { return new IteradorMenorEspera(atracciones); }
    public int aforoActual() { return ContadorAforo.getInstancia().dentro; }
}
public class Main {
    static String recorrer(IteradorAtracciones it) {
        String texto = "";
        while (it.tieneSiguiente()) {
            texto = texto + it.siguiente().nombre;
            if (it.tieneSiguiente()) {
                texto = texto + ", ";
            }
        }
        return texto;
    }
    public static void main(String[] args) {
        Parque parque = new Parque();
        System.out.println("=== Caso 3 · Req. 3 (Singleton) ===");
        Puerta norte = new Puerta();
        Puerta sur = new Puerta();
        for (int i = 0; i < 3; i++) {
            norte.ingresar();
        }
        sur.salir();
        System.out.println("Aforo actual: " + parque.aforoActual() + " (las dos puertas usan el mismo contador)");
        while (parque.aforoActual() < ContadorAforo.MAXIMO) {
            norte.ingresar();
        }
        System.out.println("Con 5,000 visitantes: " + sur.ingresar());
        System.out.println("\n=== Caso 4 · Req. 4 (Iterator) ===");
        parque.agregar(new Atraccion("Montaña Rusa", 300, false, 40));
        parque.agregar(new Atraccion("Carrusel", 50, true, 10));
        parque.agregar(new Atraccion("Tazas", 120, true, 5));
        System.out.println("Cercanía: " + recorrer(parque.porCercania()));
        System.out.println("Niños: " + recorrer(parque.aptasNinos()));
        System.out.println("Espera: " + recorrer(parque.porEspera()));
    }
}

// Ejercicio 32: CharlaYa - Mediator (R1) + Iterator (R4)
import java.util.*;
interface Mediador {
    void agregar(Usuario u);
    void enviar(Usuario de, String texto);
}
class Usuario {
    String nombre;
    private Mediador sala;
    Usuario(String nombre, Mediador sala) {
        this.nombre = nombre;
        this.sala = sala;
        sala.agregar(this);
    }
    public void escribir(String texto) { sala.enviar(this, texto); }
    public void recibir(String texto) { System.out.println(nombre + " recibe: " + texto); }
}
interface IteradorHistorial {
    boolean hasNext();
    ArrayList<String> next();
}
interface Historial {
    IteradorHistorial crearIterador();
    IteradorHistorial crearIteradorMenciones(String nombre);
}
class Sala implements Mediador, Historial {
    private ArrayList<Usuario> miembros = new ArrayList<>();
    private ArrayList<String> mensajes = new ArrayList<>();
    private HashSet<Usuario> silenciados = new HashSet<>();
    public void agregar(Usuario u) { miembros.add(u); }
    public void silenciar(Usuario u) { silenciados.add(u); }
    public void enviar(Usuario de, String texto) {
        if (silenciados.contains(de)) {
            System.out.println(de.nombre + " está silenciado: su mensaje no llega a nadie");
            return;
        }
        mensajes.add(texto);
        for (Usuario u : miembros) {
            if (u != de) {
                u.recibir(texto);
            }
        }
    }
    public IteradorHistorial crearIterador() { return new PaginasIterator(mensajes); }
    public IteradorHistorial crearIteradorMenciones(String nombre) { return new MencionesIterator(mensajes, nombre); }
}
class PaginasIterator implements IteradorHistorial {
    private ArrayList<String> recientes = new ArrayList<>();
    private int pos = 0;
    PaginasIterator(ArrayList<String> mensajes) {
        for (int i = mensajes.size() - 1; i >= 0; i--) {
            recientes.add(mensajes.get(i));
        }
    }
    public boolean hasNext() { return pos < recientes.size(); }
    public ArrayList<String> next() {
        ArrayList<String> pagina = new ArrayList<>();
        int fin = Math.min(pos + 20, recientes.size());
        while (pos < fin) {
            pagina.add(recientes.get(pos));
            pos++;
        }
        return pagina;
    }
}
class MencionesIterator extends PaginasIterator {
    MencionesIterator(ArrayList<String> mensajes, String nombre) { super(filtrar(mensajes, nombre)); }
    private static ArrayList<String> filtrar(ArrayList<String> mensajes, String nombre) {
        ArrayList<String> menciones = new ArrayList<>();
        for (String m : mensajes) {
            if (m.contains("@" + nombre)) {
                menciones.add(m);
            }
        }
        return menciones;
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Mediator) ===");
        Sala sala = new Sala();
        Usuario ana = new Usuario("Ana", sala);
        Usuario beto = new Usuario("Beto", sala);
        Usuario carla = new Usuario("Carla", sala);
        ana.escribir("Hola");
        sala.silenciar(beto);
        beto.escribir("¿Qué tal?");
        System.out.println("\n=== Caso 4 · Req. 4 (Iterator) ===");
        Sala grande = new Sala();
        Usuario luis = new Usuario("Luis", grande);
        for (int i = 1; i <= 45; i++) {
            if (i % 15 == 0) {
                luis.escribir("Mensaje " + i + " @Ana");
            } else {
                luis.escribir("Mensaje " + i);
            }
        }
        IteradorHistorial paginas = grande.crearIterador();
        while (paginas.hasNext()) {
            ArrayList<String> pagina = paginas.next();
            System.out.println("Página de " + pagina.size() + " mensajes, desde " + pagina.get(0));
        }
        IteradorHistorial menciones = grande.crearIteradorMenciones("Ana");
        while (menciones.hasNext()) {
            System.out.println("Menciones a Ana: " + menciones.next());
        }
    }
}

// Ejercicio 33: EncuestaFácil - Mediator (R1) + Memento (R4)
import java.util.*;
interface Mediador {
    void cambio();
}
abstract class Control {
    protected Mediador mediador;
    Control(Mediador mediador) { this.mediador = mediador; }
}
class Pregunta extends Control {
    String texto;
    boolean obligatoria;
    boolean visible = true;
    boolean habilitada = true;
    String respuesta;
    Pregunta(Mediador m, String texto, boolean obligatoria) {
        super(m);
        this.texto = texto;
        this.obligatoria = obligatoria;
    }
    public void responder(String r) {
        respuesta = r;
        mediador.cambio();
    }
}
class BotonEnviar extends Control {
    boolean habilitado = false;
    BotonEnviar(Mediador m) { super(m); }
}
class Progreso {
    private final String[] respuestas;
    private final int pagina;
    Progreso(String[] respuestas, int pagina) {
        this.respuestas = respuestas;
        this.pagina = pagina;
    }
    String getRespuesta(int i) { return respuestas[i]; }
    int getPagina() { return pagina; }
}
class FormularioDinamico implements Mediador {
    Pregunta nombre = new Pregunta(this, "Nombre", true);
    Pregunta transporte = new Pregunta(this, "Medio de transporte", true);
    Pregunta otro = new Pregunta(this, "Otro, ¿cuál?", false);
    Pregunta tieneAuto = new Pregunta(this, "¿Tienes auto?", true);
    Pregunta marcaAuto = new Pregunta(this, "Marca del auto", true);
    Pregunta placaAuto = new Pregunta(this, "Placa del auto", true);
    BotonEnviar enviar = new BotonEnviar(this);
    private Pregunta[] preguntas = {nombre, transporte, otro, tieneAuto, marcaAuto, placaAuto};
    int pagina = 1;
    FormularioDinamico() {
        otro.habilitada = false;
    }
    public void cambio() {
        boolean conAuto = !"No".equals(tieneAuto.respuesta);
        marcaAuto.visible = conAuto;
        placaAuto.visible = conAuto;
        otro.habilitada = "Otro".equals(transporte.respuesta);
        boolean completo = true;
        for (Pregunta p : preguntas) {
            if (p.obligatoria && p.visible && p.respuesta == null) {
                completo = false;
            }
        }
        enviar.habilitado = completo;
    }
    public Progreso guardar() {
        String[] respuestas = new String[preguntas.length];
        for (int i = 0; i < preguntas.length; i++) {
            respuestas[i] = preguntas[i].respuesta;
        }
        return new Progreso(respuestas, pagina);
    }
    public void restaurar(Progreso p) {
        pagina = p.getPagina();
        for (int i = 0; i < preguntas.length; i++) {
            preguntas[i].respuesta = p.getRespuesta(i);
        }
        cambio();
    }
}
class AlmacenProgreso {
    private Progreso progreso;
    public void guardar(FormularioDinamico f) { progreso = f.guardar(); }
    public void continuar(FormularioDinamico f) { f.restaurar(progreso); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Mediator) ===");
        FormularioDinamico f = new FormularioDinamico();
        f.nombre.responder("Ana");
        f.transporte.responder("Otro");
        System.out.println("Campo de texto habilitado: " + f.otro.habilitada);
        f.tieneAuto.responder("Sí");
        System.out.println("Con auto, Enviar habilitado: " + f.enviar.habilitado);
        f.tieneAuto.responder("No");
        System.out.println("Preguntas del auto ocultas: " + !f.marcaAuto.visible + " · Enviar habilitado: " + f.enviar.habilitado);
        System.out.println("\n=== Caso 4 · Req. 4 (Memento) ===");
        AlmacenProgreso almacen = new AlmacenProgreso();
        FormularioDinamico f1 = new FormularioDinamico();
        f1.nombre.responder("Luis");
        f1.tieneAuto.responder("No");
        f1.pagina++;
        almacen.guardar(f1);
        FormularioDinamico f2 = new FormularioDinamico();
        almacen.continuar(f2);
        System.out.println("Continúa en la página " + f2.pagina + " con las respuestas de la página 1: " + f2.nombre.respuesta + ", " + f2.tieneAuto.respuesta);
    }
}

// Ejercicio 34: ParkCity - Strategy (R2) + Decorator (R4)
interface Plan {
    int cobrar(int minutos);
    String detalle();
}
class PorHora implements Plan {
    public int cobrar(int minutos) {
        int horas = (minutos + 59) / 60;
        return 3 * horas;
    }
    public String detalle() { return "Estacionamiento"; }
}
class TarifaFija implements Plan {
    public int cobrar(int minutos) { return 20; }
    public String detalle() { return "Estacionamiento"; }
}
class AbonadoMensual implements Plan {
    public int cobrar(int minutos) { return 0; }
    public String detalle() { return "Estacionamiento"; }
}
class Adicional implements Plan {
    private Plan base;
    private String nombre;
    private int precio;
    Adicional(Plan base, String nombre, int precio) {
        this.base = base;
        this.nombre = nombre;
        this.precio = precio;
    }
    public int cobrar(int minutos) { return base.cobrar(minutos) + precio; }
    public String detalle() { return base.detalle() + " + " + nombre; }
}
class Estadia {
    private Plan plan;
    private int minutos;
    Estadia(Plan plan, int minutos) {
        this.plan = plan;
        this.minutos = minutos;
    }
    String total() { return "$$" + plan.cobrar(minutos) + ".00"; }
    String comprobante() { return plan.detalle() + " -> " + total(); }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (Strategy) ===");
        Estadia porHora = new Estadia(new PorHora(), 130);
        Estadia fija = new Estadia(new TarifaFija(), 130);
        Estadia abonado = new Estadia(new AbonadoMensual(), 130);
        System.out.println("Por hora: " + porHora.total() + " · Tarifa plana: " + fija.total() + " · Abonado: " + abonado.total());
        System.out.println("\n=== Caso 4 · Req. 4 (Decorator) ===");
        Plan conLavado = new Adicional(new PorHora(), "Lavado", 15);
        Plan conServicios = new Adicional(conLavado, "Valet", 8);
        System.out.println(new Estadia(conServicios, 130).comprobante());
        Plan conTodo = new Adicional(new Adicional(new AbonadoMensual(), "Valet", 8), "Carga eléctrica", 10);
        System.out.println(new Estadia(conTodo, 130).comprobante());
    }
}

// Ejercicio 35: StreamTV - Proxy (R1) + Adapter (R2)
import java.util.*;
interface ReproductorPlataforma {
    String reproducir(String idVideo, String calidad);
}
class UltraPlayer {
    public String iniciar(String ruta, String resolucion) { return "UltraPlayer: " + ruta + " a " + resolucion; }
}
class UltraPlayerAdapter implements ReproductorPlataforma {
    private UltraPlayer ultra = new UltraPlayer();
    public String reproducir(String idVideo, String calidad) {
        String ruta = "/videos/" + idVideo + ".mp4";
        String resolucion = "1920x1080";
        if (calidad.equals("4K")) {
            resolucion = "3840x2160";
        }
        return ultra.iniciar(ruta, resolucion);
    }
}
interface Video {
    String getId();
    String reproducir(String calidad);
}
class VideoReal implements Video {
    private String id;
    private ReproductorPlataforma reproductor;
    VideoReal(String id, ReproductorPlataforma reproductor) {
        this.id = id;
        this.reproductor = reproductor;
        System.out.println("Descargando archivo de " + id);
    }
    public String getId() { return id; }
    public String reproducir(String calidad) { return reproductor.reproducir(id, calidad); }
}
class VideoProxy implements Video {
    private String id;
    private ReproductorPlataforma reproductor;
    private VideoReal copia;
    private long ultimaVista;
    VideoProxy(String id, ReproductorPlataforma reproductor) {
        this.id = id;
        this.reproductor = reproductor;
    }
    public String getId() { return id; }
    public String reproducir(String calidad) {
        long ahora = System.currentTimeMillis();
        if (copia == null || ahora - ultimaVista > 3600000) {
            copia = new VideoReal(id, reproductor);
        } else {
            System.out.println("Usando la copia local de " + id);
        }
        ultimaVista = ahora;
        return copia.reproducir(calidad);
    }
}
public class Main {
    public static void main(String[] args) {
        ReproductorPlataforma reproductor = new UltraPlayerAdapter();
        System.out.println("=== Caso 1 · Req. 1 (Proxy) ===");
        ArrayList<Video> catalogo = new ArrayList<>();
        catalogo.add(new VideoProxy("V-100", reproductor));
        catalogo.add(new VideoProxy("V-200", reproductor));
        catalogo.add(new VideoProxy("V-300", reproductor));
        for (Video v : catalogo) {
            System.out.println("Catálogo: " + v.getId());
        }
        System.out.println(catalogo.get(0).reproducir("HD"));
        System.out.println(catalogo.get(0).reproducir("HD"));
        System.out.println("\n=== Caso 2 · Req. 2 (Adapter) ===");
        System.out.println(reproductor.reproducir("V-900", "4K"));
    }
}

// Ejercicio 36: TalentoHumano - Composite (R2) + Memento (R4)
import java.util.*;
interface Unidad {
    int costo();
}
class Empleado implements Unidad {
    String nombre;
    private int mensual;
    Empleado(String nombre, int mensual) {
        this.nombre = nombre;
        this.mensual = mensual;
    }
    public int costo() { return mensual; }
}
class Estructura {
    private HashMap<Area, ArrayList<Unidad>> copias;
    Estructura(HashMap<Area, ArrayList<Unidad>> copias) { this.copias = copias; }
    ArrayList<Area> getAreas() { return new ArrayList<Area>(copias.keySet()); }
    ArrayList<Unidad> getHijos(Area a) { return new ArrayList<Unidad>(copias.get(a)); }
}
class Area implements Unidad {
    String nombre;
    private ArrayList<Unidad> hijos = new ArrayList<>();
    Area(String nombre) { this.nombre = nombre; }
    public void agregar(Unidad u) { hijos.add(u); }
    public void quitar(Unidad u) { hijos.remove(u); }
    public boolean contiene(Unidad u) { return hijos.contains(u); }
    public int costo() {
        int total = 0;
        for (Unidad u : hijos) {
            total = total + u.costo();
        }
        return total;
    }
    public Estructura guardar() {
        HashMap<Area, ArrayList<Unidad>> copias = new HashMap<>();
        registrar(copias);
        return new Estructura(copias);
    }
    private void registrar(HashMap<Area, ArrayList<Unidad>> copias) {
        copias.put(this, new ArrayList<Unidad>(hijos));
        for (Unidad u : hijos) {
            if (u instanceof Area) {
                Area sub = (Area) u;
                sub.registrar(copias);
            }
        }
    }
    public void restaurar(Estructura e) {
        for (Area a : e.getAreas()) {
            a.hijos = e.getHijos(a);
        }
    }
}
class RecursosHumanos {
    private Estructura guardado;
    public void guardar(Area organigrama) { guardado = organigrama.guardar(); }
    public void cancelar(Area organigrama) { organigrama.restaurar(guardado); }
}
public class Main {
    static String dinero(int monto) {
        String resto = "" + monto % 1000;
        while (resto.length() < 3) {
            resto = "0" + resto;
        }
        if (monto >= 1000) {
            return "$$" + monto / 1000 + "," + resto + ".00";
        }
        return "$$" + monto + ".00";
    }
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (Composite) ===");
        Area soporte = new Area("Soporte");
        soporte.agregar(new Empleado("Diego", 2000));
        Area sistemas = new Area("Sistemas");
        sistemas.agregar(new Empleado("Ana", 3000));
        sistemas.agregar(new Empleado("Beto", 120 * 15));
        sistemas.agregar(new Empleado("Carla", 1025));
        sistemas.agregar(soporte);
        System.out.println("Soporte: " + dinero(soporte.costo()) + " · Sistemas: " + dinero(sistemas.costo()));
        System.out.println("\n=== Caso 4 · Req. 4 (Memento) ===");
        Area tecnologia = new Area("Gerencia de Tecnología");
        tecnologia.agregar(sistemas);
        Area operaciones = new Area("Gerencia de Operaciones");
        Area empresa = new Area("Empresa");
        empresa.agregar(tecnologia);
        empresa.agregar(operaciones);
        RecursosHumanos rrhh = new RecursosHumanos();
        rrhh.guardar(empresa);
        sistemas.quitar(soporte);
        operaciones.agregar(soporte);
        System.out.println("Tras mover, Soporte dentro de Sistemas: " + sistemas.contiene(soporte));
        rrhh.cancelar(empresa);
        System.out.println("Tras cancelar, Soporte dentro de Sistemas: " + sistemas.contiene(soporte)
                + " · dentro de Operaciones: " + operaciones.contiene(soporte));
    }
}

// Ejercicio 37: VotoClaro - Singleton (R1) + Proxy (R2)
import java.util.*;

interface ServicioVotacion {
    String registrarVoto(String dni);
}

class UrnaElectronica implements ServicioVotacion {
    private static final UrnaElectronica INSTANCIA = new UrnaElectronica();
    int total;

    private UrnaElectronica() {
    }

    static UrnaElectronica getInstancia() {
        return INSTANCIA;
    }

    public String registrarVoto(String dni) {
        total++;
        return "Voto registrado";
    }
}

class VerificadorVotante implements ServicioVotacion {
    private final ServicioVotacion urna;
    private final HashSet<String> habilitados = new HashSet<String>();
    private final HashSet<String> yaVotaron = new HashSet<String>();
    final ArrayList<Long> intentos = new ArrayList<Long>();

    VerificadorVotante(ServicioVotacion urna) {
        this.urna = urna;
    }

    void habilitar(String dni) {
        habilitados.add(dni);
    }

    public String registrarVoto(String dni) {
        intentos.add(System.currentTimeMillis());
        if (!habilitados.contains(dni)) {
            return "Rechazado: no habilitado";
        }
        if (yaVotaron.contains(dni)) {
            return "Rechazado: ya votó";
        }
        yaVotaron.add(dni);
        return urna.registrarVoto(dni);
    }
}

class Terminal {
    UrnaElectronica obtenerUrna() {
        return UrnaElectronica.getInstancia();
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Singleton) ===");
        Terminal t1 = new Terminal();
        Terminal t2 = new Terminal();
        t1.obtenerUrna().registrarVoto("222");
        t2.obtenerUrna().registrarVoto("333");
        System.out.println("¿Misma urna? " + (t1.obtenerUrna() == t2.obtenerUrna()) + " · Votos: " + t1.obtenerUrna().total);

        System.out.println("\n=== Caso 2 · Req. 2 (Proxy) ===");
        VerificadorVotante verificador = new VerificadorVotante(UrnaElectronica.getInstancia());
        verificador.habilitar("111");
        String r1 = verificador.registrarVoto("111");
        String r2 = verificador.registrarVoto("111");
        String r3 = verificador.registrarVoto("999");
        System.out.println(r1 + " · " + r2 + " · " + r3);
        System.out.println(verificador.intentos.size() + " intentos registrados");
    }
}

// Ejercicio 38: ImprimeYa - Adapter (R3) + Proxy (R4)
import java.util.*;

interface Impresora {
    String imprimir(String doc, int paginas, boolean color);
}

class PrintMaxDriver {
    String print(ArrayList<String> paginas, String modo) {
        return "PrintMax: " + paginas.size() + " páginas, modo " + modo;
    }
}

class PrintMaxAdapter implements Impresora {
    private final PrintMaxDriver driver = new PrintMaxDriver();

    public String imprimir(String doc, int paginas, boolean color) {
        ArrayList<String> lista = new ArrayList<String>();
        for (int i = 1; i <= paginas; i++) {
            lista.add(doc + " p." + i);
        }
        String modo = "BW";
        if (color) {
            modo = "COLOR";
        }
        return driver.print(lista, modo);
    }
}

class ControlCuotaProxy implements Impresora {
    private static final int CUOTA = 200;
    private final Impresora impresora;
    private int usadas;

    ControlCuotaProxy(Impresora impresora, int usadas) {
        this.impresora = impresora;
        this.usadas = usadas;
    }

    public String imprimir(String doc, int paginas, boolean color) {
        if (usadas + paginas > CUOTA) {
            return "Rechazado: supera la cuota";
        }
        impresora.imprimir(doc, paginas, color);
        usadas = usadas + paginas;
        return "Impreso (" + usadas + "/" + CUOTA + ")";
    }
}

public class Main {
    public static void main(String[] args) {
        Impresora printMax = new PrintMaxAdapter();

        System.out.println("=== Caso 3 · Req. 3 (Adapter) ===");
        System.out.println(printMax.imprimir("afiche.pdf", 3, true));

        System.out.println("\n=== Caso 4 · Req. 4 (Proxy) ===");
        Impresora conCuota = new ControlCuotaProxy(printMax, 190);
        String r1 = conCuota.imprimir("tesis.pdf", 5, false);
        String r2 = conCuota.imprimir("anexos.pdf", 10, false);
        System.out.println(r1 + " · " + r2);
    }
}

// Ejercicio 39: TallerPro - Builder (R2) + State (R3)
import java.util.*;

abstract class Estado {
    abstract String nombre();

    void avanzar(Orden o) {
    }

    void aceptar(Orden o) {
    }

    void rechazar(Orden o) {
    }

    String entregar(Orden o) {
        return "No se puede entregar: la orden no está lista";
    }
}

class Recibida extends Estado {
    String nombre() {
        return "Recibida";
    }

    void avanzar(Orden o) {
        o.estado = new EnDiagnostico();
    }
}

class EnDiagnostico extends Estado {
    String nombre() {
        return "En diagnóstico";
    }

    void avanzar(Orden o) {
        if (o.requiereAprobacion) {
            o.estado = new EnEspera();
        } else {
            o.estado = new EnReparacion();
        }
    }
}

class EnEspera extends Estado {
    String nombre() {
        return "En espera de aprobación";
    }

    void aceptar(Orden o) {
        o.estado = new EnReparacion();
    }

    void rechazar(Orden o) {
        o.sinReparar = true;
        o.estado = new Lista();
    }
}

class EnReparacion extends Estado {
    String nombre() {
        return "En reparación";
    }

    void avanzar(Orden o) {
        o.estado = new Lista();
    }
}

class Lista extends Estado {
    String nombre() {
        return "Lista";
    }

    String entregar(Orden o) {
        o.estado = new Entregada();
        return "Orden entregada";
    }
}

class Entregada extends Estado {
    String nombre() {
        return "Entregada";
    }
}

class Orden {
    final String vehiculo;
    final String cliente;
    final ArrayList<String> trabajos = new ArrayList<String>();
    Estado estado = new Recibida();
    boolean requiereAprobacion;
    boolean sinReparar;

    Orden(String vehiculo, String cliente) {
        this.vehiculo = vehiculo;
        this.cliente = cliente;
    }

    void avanzar() {
        estado.avanzar(this);
    }

    void aceptar() {
        estado.aceptar(this);
    }

    void rechazar() {
        estado.rechazar(this);
    }

    String entregar() {
        return estado.entregar(this);
    }

    String estadoActual() {
        if (sinReparar) {
            return estado.nombre() + " (sin reparar)";
        }
        return estado.nombre();
    }

    String resumen() {
        return vehiculo + " de " + cliente + ": " + trabajos;
    }
}

class OrdenBuilder {
    private final Orden orden;

    OrdenBuilder(String vehiculo, String cliente) {
        orden = new Orden(vehiculo, cliente);
    }

    OrdenBuilder cambioAceite() {
        orden.trabajos.add("Cambio de aceite");
        return this;
    }

    OrdenBuilder alineamiento() {
        orden.trabajos.add("Alineamiento");
        return this;
    }

    OrdenBuilder frenos() {
        orden.trabajos.add("Frenos");
        return this;
    }

    OrdenBuilder revisionElectrica() {
        orden.trabajos.add("Revisión eléctrica");
        return this;
    }

    OrdenBuilder lavado() {
        orden.trabajos.add("Lavado");
        return this;
    }

    OrdenBuilder observaciones(String texto) {
        orden.trabajos.add("Observaciones: " + texto);
        return this;
    }

    Orden build() {
        return orden;
    }
}

class DirectorOrdenes {
    Orden mantenimiento10000(String vehiculo, String cliente) {
        OrdenBuilder builder = new OrdenBuilder(vehiculo, cliente);
        builder.cambioAceite().alineamiento().frenos();
        return builder.build();
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (Builder) ===");
        DirectorOrdenes director = new DirectorOrdenes();
        Orden paquete = director.mantenimiento10000("Auto", "Ana");
        Orden soloFrenos = new OrdenBuilder("Moto", "Luis").frenos().build();
        System.out.println("Mantenimiento 10,000 km -> " + paquete.resumen());
        System.out.println("Solo frenos -> " + soloFrenos.resumen());

        System.out.println("\n=== Caso 3 · Req. 3 (State) ===");
        Orden rechazada = new OrdenBuilder("Camión", "Eva").build();
        rechazada.requiereAprobacion = true;
        rechazada.avanzar();
        rechazada.avanzar();
        System.out.println("Estado: " + rechazada.estadoActual());
        rechazada.rechazar();
        System.out.println("Estado: " + rechazada.estadoActual());
        System.out.println(rechazada.entregar());

        Orden enReparacion = new OrdenBuilder("Auto", "Raúl").build();
        enReparacion.avanzar();
        enReparacion.avanzar();
        System.out.println("Estado: " + enReparacion.estadoActual());
        System.out.println(enReparacion.entregar());
    }
}

// Ejercicio 40: Cartas Arcanas - Prototype (R1) + Iterator (R2)
import java.util.*;

class Carta {
    String nombre;
    String tipo;
    int costo;
    int ataque;

    Carta(String nombre, String tipo, int costo, int ataque) {
        this.nombre = nombre;
        this.tipo = tipo;
        this.costo = costo;
        this.ataque = ataque;
    }

    Carta clonar() {
        return new Carta(nombre, tipo, costo, ataque);
    }

    void mejorar(int extra) {
        ataque = ataque + extra;
    }
}

interface IteradorCartas {
    boolean hayMas();

    Carta siguiente();
}

class IteradorLista implements IteradorCartas {
    private final ArrayList<Carta> lista;
    private int posicion = 0;

    IteradorLista(ArrayList<Carta> lista) {
        this.lista = lista;
    }

    public boolean hayMas() {
        return posicion < lista.size();
    }

    public Carta siguiente() {
        Carta carta = lista.get(posicion);
        posicion++;
        return carta;
    }
}

class Mazo {
    final ArrayList<Carta> cartas = new ArrayList<Carta>();

    void agregar(Carta plantilla) {
        cartas.add(plantilla.clonar());
    }

    IteradorCartas ordenActual() {
        return new IteradorLista(cartas);
    }

    IteradorCartas soloTipo(String tipo) {
        ArrayList<Carta> filtradas = new ArrayList<Carta>();
        for (int i = 0; i < cartas.size(); i++) {
            if (cartas.get(i).tipo.equals(tipo)) {
                filtradas.add(cartas.get(i));
            }
        }
        return new IteradorLista(filtradas);
    }

    IteradorCartas porCosto() {
        ArrayList<Carta> ordenadas = new ArrayList<Carta>(cartas);
        for (int i = 0; i < ordenadas.size() - 1; i++) {
            for (int j = 0; j < ordenadas.size() - 1 - i; j++) {
                if (ordenadas.get(j).costo > ordenadas.get(j + 1).costo) {
                    Carta temporal = ordenadas.get(j);
                    ordenadas.set(j, ordenadas.get(j + 1));
                    ordenadas.set(j + 1, temporal);
                }
            }
        }
        return new IteradorLista(ordenadas);
    }
}

public class Main {
    static String recorrer(IteradorCartas it) {
        StringBuilder texto = new StringBuilder();
        while (it.hayMas()) {
            if (texto.length() > 0) {
                texto.append(", ");
            }
            texto.append(it.siguiente().nombre);
        }
        return texto.toString();
    }

    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Prototype) ===");
        Carta dragon = new Carta("Dragón Rojo", "criatura", 6, 5);
        Mazo mazo = new Mazo();
        mazo.agregar(dragon);
        mazo.agregar(dragon);
        mazo.cartas.get(0).mejorar(2);
        System.out.println("Copia 1: " + mazo.cartas.get(0).ataque + " · Copia 2: " + mazo.cartas.get(1).ataque + " · Original: " + dragon.ataque);

        System.out.println("\n=== Caso 2 · Req. 2 (Iterator) ===");
        Mazo otro = new Mazo();
        otro.agregar(new Carta("Bola de fuego", "hechizo", 3, 4));
        otro.agregar(new Carta("Gólem", "criatura", 5, 6));
        otro.agregar(new Carta("Rayo", "hechizo", 1, 2));
        System.out.println("Orden actual: " + recorrer(otro.ordenActual()));
        System.out.println("Solo hechizos: " + recorrer(otro.soloTipo("hechizo")));
        System.out.println("Por costo: " + recorrer(otro.porCosto()));
    }
}

// Ejercicio 41: MeteoRed - Observer (R1) + Singleton (R4)
import java.util.*;

class ConfiguracionEstacion {
    static int cargas;
    private static final ConfiguracionEstacion INSTANCIA = new ConfiguracionEstacion();
    final String codigo;
    final String ubicacion;
    final String unidades;

    private ConfiguracionEstacion() {
        cargas++;
        codigo = "EST-01";
        ubicacion = "Cochabamba";
        unidades = "°C";
    }

    static ConfiguracionEstacion getInstancia() {
        return INSTANCIA;
    }
}

interface ObservadorClima {
    void actualizar(double celsius);
}

class PantallaActual implements ObservadorClima {
    public void actualizar(double celsius) {
        System.out.println("Condiciones actuales: " + Math.round(celsius) + " °C");
    }
}

class PantallaEstadisticas implements ObservadorClima {
    private double suma;
    private int cantidad;

    public void actualizar(double celsius) {
        suma = suma + celsius;
        cantidad++;
        System.out.println("Estadísticas: promedio " + Math.round(suma / cantidad) + " " + config().unidades);
    }

    ConfiguracionEstacion config() {
        return ConfiguracionEstacion.getInstancia();
    }
}

class SistemaAlertas implements ObservadorClima {
    public void actualizar(double celsius) {
        if (celsius > 35) {
            System.out.println("Alerta: " + Math.round(celsius) + " " + config().unidades);
        }
    }

    ConfiguracionEstacion config() {
        return ConfiguracionEstacion.getInstancia();
    }
}

class EstacionMeteorologica {
    private final ArrayList<ObservadorClima> pantallas = new ArrayList<ObservadorClima>();

    void conectar(ObservadorClima pantalla) {
        pantallas.add(pantalla);
    }

    void desconectar(ObservadorClima pantalla) {
        pantallas.remove(pantalla);
    }

    void nuevaMedicion(double celsius) {
        for (int i = 0; i < pantallas.size(); i++) {
            pantallas.get(i).actualizar(celsius);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Observer) ===");
        EstacionMeteorologica estacion = new EstacionMeteorologica();
        PantallaEstadisticas estadisticas = new PantallaEstadisticas();
        SistemaAlertas alertas = new SistemaAlertas();
        estacion.conectar(new PantallaActual());
        estacion.conectar(estadisticas);
        estacion.conectar(alertas);
        estacion.nuevaMedicion(30);
        estacion.nuevaMedicion(36);

        System.out.println("\n=== Caso 4 · Req. 4 (Singleton) ===");
        boolean misma = estadisticas.config() == alertas.config();
        System.out.println("¿Misma instancia? " + misma + " · Veces cargada: " + ConfiguracionEstacion.cargas);
        System.out.println("Estación " + alertas.config().codigo + " en " + alertas.config().ubicacion);
    }
}

// Ejercicio 42: OfiSuite - Command (R2) + Composite (R3)
import java.util.*;

abstract class ElementoMenu {
    final String nombre;
    boolean activo = true;

    ElementoMenu(String nombre) {
        this.nombre = nombre;
    }

    void desactivar() {
        activo = false;
    }

    String mostrar() {
        if (activo) {
            return nombre + " activo";
        }
        return nombre + " desactivado";
    }
}

class Opcion extends ElementoMenu {
    private final Comando comando;

    Opcion(String nombre, Comando comando) {
        super(nombre);
        this.comando = comando;
    }

    void elegir() {
        if (activo) {
            comando.ejecutar();
        }
    }
}

class Submenu extends ElementoMenu {
    private final ArrayList<ElementoMenu> hijos = new ArrayList<ElementoMenu>();

    Submenu(String nombre) {
        super(nombre);
    }

    Submenu agregar(ElementoMenu elemento) {
        hijos.add(elemento);
        return this;
    }

    void desactivar() {
        super.desactivar();
        for (int i = 0; i < hijos.size(); i++) {
            hijos.get(i).desactivar();
        }
    }

    String mostrar() {
        String texto = super.mostrar();
        for (int i = 0; i < hijos.size(); i++) {
            texto = texto + ", " + hijos.get(i).mostrar();
        }
        return texto;
    }
}

interface Comando {
    void ejecutar();

    void deshacer();
}

class Documento {
    String texto = "";
    boolean guardado = false;
}

class Portapapeles {
    String contenido = "";
}

class Guardar implements Comando {
    private final Documento doc;
    private boolean antes;

    Guardar(Documento doc) {
        this.doc = doc;
    }

    public void ejecutar() {
        antes = doc.guardado;
        doc.guardado = true;
    }

    public void deshacer() {
        doc.guardado = antes;
    }
}

class Copiar implements Comando {
    private final Documento doc;
    private final Portapapeles portapapeles;
    private String antes;

    Copiar(Documento doc, Portapapeles portapapeles) {
        this.doc = doc;
        this.portapapeles = portapapeles;
    }

    public void ejecutar() {
        antes = portapapeles.contenido;
        portapapeles.contenido = doc.texto;
    }

    public void deshacer() {
        portapapeles.contenido = antes;
    }
}

class Pegar implements Comando {
    private final Documento doc;
    private final Portapapeles portapapeles;
    private String antes;

    Pegar(Documento doc, Portapapeles portapapeles) {
        this.doc = doc;
        this.portapapeles = portapapeles;
    }

    public void ejecutar() {
        antes = doc.texto;
        doc.texto = doc.texto + portapapeles.contenido;
    }

    public void deshacer() {
        doc.texto = antes;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (Command) ===");
        Documento origen = new Documento();
        origen.texto = "abc";
        Documento doc = new Documento();
        Portapapeles portapapeles = new Portapapeles();
        new Opcion("Copiar", new Copiar(origen, portapapeles)).elegir();
        Pegar pegar = new Pegar(doc, portapapeles);
        Opcion menu = new Opcion("Menú Pegar", pegar);
        Opcion atajo = new Opcion("Ctrl+V", pegar);
        menu.elegir();
        atajo.elegir();
        System.out.print("Documento: “" + doc.texto + "”");
        pegar.deshacer();
        System.out.println(" → “" + doc.texto + "”");

        System.out.println("\n=== Caso 3 · Req. 3 (Composite) ===");
        Documento otro = new Documento();
        Submenu exportar = new Submenu("Exportar");
        exportar.agregar(new Opcion("PDF", new Guardar(otro)));
        exportar.agregar(new Opcion("Word", new Guardar(otro)));
        exportar.desactivar();
        System.out.println(exportar.mostrar());
    }
}

// Ejercicio 43: VetCuida - Builder (R1) + Visitor (R2)
import java.util.*;

abstract class Mascota {
    String nombre;
    String especie;
    String duenio;
    String raza;
    Double peso;
    String alergias;
    String vacunas;
    String cirugias;
    String observaciones;

    abstract void aceptar(VisitanteMascota v);

    String ficha() {
        String texto = nombre + " (" + especie + ", dueño " + duenio + ")";
        if (raza != null) {
            texto = texto + ", raza " + raza;
        }
        if (peso != null) {
            texto = texto + ", peso " + peso + " kg";
        }
        if (alergias != null) {
            texto = texto + ", alergias " + alergias;
        }
        if (vacunas != null) {
            texto = texto + ", vacunas " + vacunas;
        }
        if (cirugias != null) {
            texto = texto + ", cirugías " + cirugias;
        }
        if (observaciones != null) {
            texto = texto + ", observaciones " + observaciones;
        }
        return texto;
    }
}

class Perro extends Mascota {
    void aceptar(VisitanteMascota v) {
        v.visitarPerro(this);
    }
}

class Gato extends Mascota {
    void aceptar(VisitanteMascota v) {
        v.visitarGato(this);
    }
}

class Ave extends Mascota {
    void aceptar(VisitanteMascota v) {
        v.visitarAve(this);
    }
}

class FichaBuilder {
    private final Mascota mascota;

    FichaBuilder(String nombre, String especie, String duenio) {
        if (especie.equals("perro")) {
            mascota = new Perro();
        } else if (especie.equals("gato")) {
            mascota = new Gato();
        } else {
            mascota = new Ave();
        }
        mascota.nombre = nombre;
        mascota.especie = especie;
        mascota.duenio = duenio;
    }

    FichaBuilder raza(String raza) {
        mascota.raza = raza;
        return this;
    }

    FichaBuilder peso(double kg) {
        mascota.peso = kg;
        return this;
    }

    FichaBuilder alergias(String alergias) {
        mascota.alergias = alergias;
        return this;
    }

    FichaBuilder vacunas(String vacunas) {
        mascota.vacunas = vacunas;
        return this;
    }

    FichaBuilder cirugias(String cirugias) {
        mascota.cirugias = cirugias;
        return this;
    }

    FichaBuilder observaciones(String observaciones) {
        mascota.observaciones = observaciones;
        return this;
    }

    Mascota build() {
        return mascota;
    }
}

interface VisitanteMascota {
    void visitarPerro(Perro p);

    void visitarGato(Gato g);

    void visitarAve(Ave a);
}

class CalculoDosis implements VisitanteMascota {
    double ml;

    public void visitarPerro(Perro p) {
        ml = 0.1 * p.peso;
    }

    public void visitarGato(Gato g) {
        ml = Math.min(0.1 * g.peso, 0.5);
    }

    public void visitarAve(Ave a) {
        ml = 0.1;
    }
}

class CarneVacunacion implements VisitanteMascota {
    String carne;

    public void visitarPerro(Perro p) {
        carne = "Carné canino de " + p.nombre + ": " + vacunasDe(p);
    }

    public void visitarGato(Gato g) {
        carne = "Carné felino de " + g.nombre + ": " + vacunasDe(g);
    }

    public void visitarAve(Ave a) {
        carne = "Carné aviar de " + a.nombre + ": " + vacunasDe(a);
    }

    private String vacunasDe(Mascota m) {
        if (m.vacunas == null) {
            return "sin vacunas registradas";
        }
        return m.vacunas;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Builder) ===");
        Mascota toby = new FichaBuilder("Toby", "perro", "Ana").peso(20).alergias("penicilina").build();
        Mascota pepe = new FichaBuilder("Pepe", "ave", "Luis").build();
        System.out.println(toby.ficha());
        System.out.println(pepe.ficha());

        System.out.println("\n=== Caso 2 · Req. 2 (Visitor) ===");
        Mascota michi = new FichaBuilder("Michi", "gato", "Carla").peso(8).vacunas("triple felina").build();
        Mascota loro = new FichaBuilder("Loro", "ave", "Dani").build();
        Mascota[] mascotas = { toby, michi, loro };
        String dosis = "";
        for (int i = 0; i < mascotas.length; i++) {
            CalculoDosis calculo = new CalculoDosis();
            mascotas[i].aceptar(calculo);
            if (i > 0) {
                dosis = dosis + " · ";
            }
            dosis = dosis + calculo.ml + " ml";
        }
        System.out.println(dosis);
        CarneVacunacion carne = new CarneVacunacion();
        michi.aceptar(carne);
        System.out.println(carne.carne);
    }
}

// Ejercicio 44: AlmaTech - Iterator (R1) + Flyweight (R3)
import java.util.*;
class Producto {
    final String nombre;
    final String descripcion;
    final String foto;
    final String dimensiones;
    final int peso;
    Producto(String nombre, String descripcion, String foto, String dimensiones, int peso) {
        this.nombre = nombre;
        this.descripcion = descripcion;
        this.foto = foto;
        this.dimensiones = dimensiones;
        this.peso = peso;
    }
}
class Unidad {
    final Producto producto;
    final String lote;
    final int pasillo;
    final int vence;
    Unidad(Producto producto, String lote, int pasillo, int vence) {
        this.producto = producto;
        this.lote = lote;
        this.pasillo = pasillo;
        this.vence = vence;
    }
}
interface IteradorInventario {
    boolean hayMas();
    Unidad siguiente();
}
class IteradorLista implements IteradorInventario {
    private final List<Unidad> lista;
    private int pos = 0;
    IteradorLista(List<Unidad> lista) {
        this.lista = lista;
    }
    public boolean hayMas() {
        return pos < lista.size();
    }
    public Unidad siguiente() {
        Unidad u = lista.get(pos);
        pos++;
        return u;
    }
}
class Inventario {
    final Map<String, Producto> productos = new HashMap<>();
    final List<Unidad> unidades = new ArrayList<>();
    Producto obtenerProducto(String nombre) {
        if (!productos.containsKey(nombre)) {
            productos.put(nombre, new Producto(nombre, "Descripción de " + nombre, nombre + ".jpg", "30x20x10 cm", 5));
        }
        return productos.get(nombre);
    }
    void registrar(String nombre, String lote, int pasillo, int vence) {
        unidades.add(new Unidad(obtenerProducto(nombre), lote, pasillo, vence));
    }
    IteradorInventario porLlegada() {
        return new IteradorLista(unidades);
    }
    IteradorInventario porUbicacion() {
        List<Unidad> orden = new ArrayList<>(unidades);
        for (int i = 0; i < orden.size() - 1; i++) {
            for (int j = 0; j < orden.size() - 1 - i; j++) {
                if (orden.get(j).pasillo > orden.get(j + 1).pasillo) {
                    Unidad temp = orden.get(j);
                    orden.set(j, orden.get(j + 1));
                    orden.set(j + 1, temp);
                }
            }
        }
        return new IteradorLista(orden);
    }
    IteradorInventario porVencer() {
        List<Unidad> proximas = new ArrayList<>();
        for (Unidad u : unidades) {
            if (u.vence <= 30) {
                proximas.add(u);
            }
        }
        return new IteradorLista(proximas);
    }
}
public class Main {
    static String recorrer(IteradorInventario it) {
        StringBuilder sb = new StringBuilder();
        while (it.hayMas()) {
            if (sb.length() > 0) {
                sb.append(", ");
            }
            sb.append(it.siguiente().producto.nombre);
        }
        return sb.toString();
    }
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Iterator) ===");
        Inventario inv = new Inventario();
        inv.registrar("A", "L-1", 2, 10);
        inv.registrar("B", "L-2", 1, 90);
        inv.registrar("C", "L-3", 3, 20);
        System.out.println("Ubicación: " + recorrer(inv.porUbicacion()) + " · Por vencer: " + recorrer(inv.porVencer()) + " · Llegada: " + recorrer(inv.porLlegada()));
        System.out.println("\n=== Caso 3 · Req. 3 (Flyweight) ===");
        Inventario almacen = new Inventario();
        for (int i = 0; i < 10000; i++) {
            almacen.registrar("Producto " + (i % 4), "L-" + i, i % 5, 100);
        }
        System.out.println(almacen.unidades.size() + " unidades · Solo existen " + almacen.productos.size() + " objetos con los datos de producto");
    }
}

// Ejercicio 45: Turbo Rally - Builder (R1) + Memento (R4)
import java.util.*;
class Auto {
    final List<String> partes = new ArrayList<>();
    List<String> potenciadores = new ArrayList<>();
    int km;
    int velocidad;
    PuntoControl guardar() {
        return new PuntoControl(km, velocidad, potenciadores);
    }
    void restaurar(PuntoControl p) {
        km = p.getKm();
        velocidad = p.getVelocidad();
        potenciadores = new ArrayList<>(p.getPotenciadores());
    }
}
class PuntoControl {
    private final int km;
    private final int velocidad;
    private final List<String> potenciadores;
    PuntoControl(int km, int velocidad, List<String> potenciadores) {
        this.km = km;
        this.velocidad = velocidad;
        this.potenciadores = new ArrayList<>(potenciadores);
    }
    int getKm() {
        return km;
    }
    int getVelocidad() {
        return velocidad;
    }
    List<String> getPotenciadores() {
        return potenciadores;
    }
}
class AutoBuilder {
    private final Auto auto = new Auto();
    AutoBuilder(String chasis) {
        auto.partes.add("chasis " + chasis);
    }
    AutoBuilder motor(String motor) {
        auto.partes.add("motor " + motor);
        return this;
    }
    AutoBuilder neumaticos(String neumaticos) {
        auto.partes.add("neumáticos " + neumaticos);
        return this;
    }
    AutoBuilder aleron(String aleron) {
        auto.partes.add("alerón " + aleron);
        return this;
    }
    AutoBuilder pintura(String pintura) {
        auto.partes.add("pintura " + pintura);
        return this;
    }
    Auto build() {
        return auto;
    }
}
class DirectorAutos {
    Auto novato() {
        return new AutoBuilder("estándar").neumaticos("de calle").build();
    }
    Auto leyenda() {
        return new AutoBuilder("reforzado").motor("V8").neumaticos("de competición").aleron("trasero").pintura("dorada").build();
    }
}
class Circuito {
    private PuntoControl ultimo;
    void puntoControl(Auto auto) {
        ultimo = auto.guardar();
    }
    void salirDePista(Auto auto) {
        auto.restaurar(ultimo);
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Builder) ===");
        DirectorAutos director = new DirectorAutos();
        Auto novato = director.novato();
        Auto leyenda = director.leyenda();
        Auto propio = new AutoBuilder("ligero").motor("V8").build();
        System.out.println("Novato: " + novato.partes);
        System.out.println("Leyenda: " + leyenda.partes);
        System.out.println("Propio: " + propio.partes);
        System.out.println("\n=== Caso 4 · Req. 4 (Memento) ===");
        Circuito circuito = new Circuito();
        Auto auto = new AutoBuilder("ligero").build();
        auto.km = 3;
        auto.velocidad = 150;
        auto.potenciadores.add("escudo");
        circuito.puntoControl(auto);
        auto.km = 4;
        auto.velocidad = 180;
        auto.potenciadores.add("turbo");
        circuito.salirDePista(auto);
        System.out.println("El auto vuelve al km " + auto.km + " a " + auto.velocidad + " km/h");
        System.out.println("Potenciadores: " + auto.potenciadores);
    }
}

