// Ejercicio 47: PuntosMás - Singleton (R3) + Facade (R4)
import java.util.*;
class RegistroPuntos {
    private static final RegistroPuntos INSTANCIA = new RegistroPuntos();
    private final Map<String, Integer> saldos = new HashMap<>();
    private RegistroPuntos() {
    }
    static RegistroPuntos getInstancia() {
        return INSTANCIA;
    }
    int consultar(String cliente) {
        if (!saldos.containsKey(cliente)) {
            return 0;
        }
        return saldos.get(cliente);
    }
    void abonar(String cliente, int puntos) {
        saldos.put(cliente, consultar(cliente) + puntos);
    }
    void gastar(String cliente, int puntos) {
        saldos.put(cliente, consultar(cliente) - puntos);
    }
}
class Inventario {
    void reservar(String premio) {
        System.out.println("2. Premio reservado: " + premio);
    }
}
class Comprobantes {
    void generar(String cliente, String premio) {
        System.out.println("4. Comprobante generado: " + cliente + " canjeó " + premio);
    }
}
class Envios {
    void programar(String premio) {
        System.out.println("5. Envío programado: " + premio);
    }
}
class CanjePremios {
    private final Inventario inventario = new Inventario();
    private final Comprobantes comprobantes = new Comprobantes();
    private final Envios envios = new Envios();
    void canjear(String cliente, String premio, int puntos) {
        RegistroPuntos registro = RegistroPuntos.getInstancia();
        if (registro.consultar(cliente) < puntos) {
            System.out.println("Saldo insuficiente");
            return;
        }
        System.out.println("1. Saldo verificado: " + registro.consultar(cliente) + " puntos");
        inventario.reservar(premio);
        registro.gastar(cliente, puntos);
        System.out.println("3. Puntos descontados: " + puntos);
        comprobantes.generar(cliente, premio);
        envios.programar(premio);
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 3 · Req. 3 (Singleton) ===");
        RegistroPuntos app = RegistroPuntos.getInstancia();
        RegistroPuntos web = RegistroPuntos.getInstancia();
        app.abonar("C-01", 1000);
        app.gastar("C-01", 300);
        System.out.println("La web muestra " + web.consultar("C-01") + " puntos");
        System.out.println("\n=== Caso 4 · Req. 4 (Facade) ===");
        CanjePremios canje = new CanjePremios();
        canje.canjear("C-01", "Mochila", 500);
        System.out.println("Saldo final: " + web.consultar("C-01") + " puntos");
    }
}

// Ejercicio 48: DevFlow - Template Method (R1) + Adapter (R4)
interface Repositorio {
    String descargar(String url, String rama);
}
class GitBoxLib {
    String clonar(int proyecto, String rama) {
        return "GitBox: proyecto " + proyecto + ", rama " + rama;
    }
}
class CodeVaultLib {
    String bajar(String token, int revision) {
        return "CodeVault: revisión " + revision;
    }
}
class GitBoxAdapter implements Repositorio {
    private final GitBoxLib lib = new GitBoxLib();
    public String descargar(String url, String rama) {
        int proyecto = Integer.parseInt(url.substring(url.indexOf("/") + 1));
        return lib.clonar(proyecto, rama);
    }
}
class CodeVaultAdapter implements Repositorio {
    private final CodeVaultLib lib = new CodeVaultLib();
    private final String token;
    CodeVaultAdapter(String token) {
        this.token = token;
    }
    public String descargar(String url, String rama) {
        int revision = Integer.parseInt(url.substring(url.indexOf("/") + 1));
        return lib.bajar(token, revision);
    }
}
abstract class Pipeline {
    final void ejecutar(Repositorio repositorio, String url, String rama) {
        descargar(repositorio, url, rama);
        instalar();
        compilar();
        probar();
        empaquetar();
    }
    void descargar(Repositorio repositorio, String url, String rama) {
        System.out.println("Descarga: " + repositorio.descargar(url, rama));
    }
    abstract void instalar();
    abstract void compilar();
    abstract void probar();
    void empaquetar() {
        System.out.println("Empaquetado: listo");
    }
}
class PipelineJava extends Pipeline {
    void instalar() {
        System.out.println("Instalación: Maven");
    }
    void compilar() {
        System.out.println("Compilación: javac");
    }
    void probar() {
        System.out.println("Pruebas: JUnit");
    }
}
class PipelinePython extends Pipeline {
    void instalar() {
        System.out.println("Instalación: pip");
    }
    void compilar() {
        System.out.println("Compilación: no aplica");
    }
    void probar() {
        System.out.println("Pruebas: pytest");
    }
}
class PipelineJavaScript extends Pipeline {
    void instalar() {
        System.out.println("Instalación: npm");
    }
    void compilar() {
        System.out.println("Compilación: webpack");
    }
    void probar() {
        System.out.println("Pruebas: jest");
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Template Method) ===");
        System.out.println("Java:");
        new PipelineJava().ejecutar(new GitBoxAdapter(), "gitbox/42", "main");
        System.out.println("Python:");
        new PipelinePython().ejecutar(new GitBoxAdapter(), "gitbox/42", "main");
        System.out.println("\n=== Caso 4 · Req. 4 (Adapter) ===");
        Repositorio gitbox = new GitBoxAdapter();
        Repositorio codevault = new CodeVaultAdapter("token-123");
        System.out.println(gitbox.descargar("gitbox/42", "main") + " · " + codevault.descargar("codevault/1057", "main"));
    }
}

// Ejercicio 49: MuseoVirtual - Composite (R1) + Iterator (R2)
import java.util.*;
interface Componente {
    int valor();
    void recolectar(List<Obra> obras);
}
class Obra implements Componente {
    final int valor;
    final int anio;
    final boolean destacada;
    Obra(int valor, int anio, boolean destacada) {
        this.valor = valor;
        this.anio = anio;
        this.destacada = destacada;
    }
    public int valor() {
        return valor;
    }
    public void recolectar(List<Obra> obras) {
        obras.add(this);
    }
}
interface IteradorObras {
    boolean hayMas();
    Obra siguiente();
}
class Recorrido implements IteradorObras {
    private final List<Obra> obras;
    private int pos = 0;
    Recorrido(List<Obra> obras) {
        this.obras = obras;
    }
    public boolean hayMas() {
        return pos < obras.size();
    }
    public Obra siguiente() {
        Obra o = obras.get(pos);
        pos++;
        return o;
    }
}
class Sala implements Componente {
    private final List<Componente> partes = new ArrayList<>();
    Sala agregar(Componente c) {
        partes.add(c);
        return this;
    }
    public int valor() {
        int total = 0;
        for (Componente c : partes) {
            total += c.valor();
        }
        return total;
    }
    public void recolectar(List<Obra> obras) {
        for (Componente c : partes) {
            c.recolectar(obras);
        }
    }
    private void ordenarPorEpoca(List<Obra> obras) {
        for (int i = 0; i < obras.size() - 1; i++) {
            for (int j = 0; j < obras.size() - 1 - i; j++) {
                if (obras.get(j).anio > obras.get(j + 1).anio) {
                    Obra temp = obras.get(j);
                    obras.set(j, obras.get(j + 1));
                    obras.set(j + 1, temp);
                }
            }
        }
    }
    IteradorObras recorridoPorSala() {
        List<Obra> obras = new ArrayList<>();
        recolectar(obras);
        return new Recorrido(obras);
    }
    IteradorObras recorridoPorEpoca() {
        List<Obra> obras = new ArrayList<>();
        recolectar(obras);
        ordenarPorEpoca(obras);
        return new Recorrido(obras);
    }
    IteradorObras recorridoDestacadas() {
        List<Obra> todas = new ArrayList<>();
        recolectar(todas);
        List<Obra> destacadas = new ArrayList<>();
        for (Obra o : todas) {
            if (o.destacada) {
                destacadas.add(o);
            }
        }
        ordenarPorEpoca(destacadas);
        return new Recorrido(destacadas);
    }
}
public class Main {
    static String dinero(int monto) {
        if (monto < 1000) {
            return "" + monto;
        }
        String resto = "" + (monto % 1000);
        while (resto.length() < 3) {
            resto = "0" + resto;
        }
        return dinero(monto / 1000) + "," + resto;
    }
    static String anios(IteradorObras it) {
        StringBuilder sb = new StringBuilder();
        while (it.hayMas()) {
            if (sb.length() > 0) {
                sb.append(", ");
            }
            sb.append(it.siguiente().anio);
        }
        return sb.toString();
    }
    public static void main(String[] args) {
        System.out.println("=== Caso 1 · Req. 1 (Composite) ===");
        Sala subsala = new Sala();
        subsala.agregar(new Obra(50000, 1700, false));
        Sala barroco = new Sala();
        barroco.agregar(new Obra(100000, 1650, false));
        barroco.agregar(new Obra(250000, 1600, false));
        barroco.agregar(subsala);
        System.out.println("Subsala: $$" + dinero(subsala.valor()) + " · Sala Barroco: $$" + dinero(barroco.valor()));
        System.out.println("\n=== Caso 2 · Req. 2 (Iterator) ===");
        Sala museo = new Sala();
        museo.agregar(new Obra(1, 1650, false));
        museo.agregar(new Obra(1, 1500, true));
        museo.agregar(new Obra(1, 1890, true));
        System.out.println("Por sala: " + anios(museo.recorridoPorSala()));
        System.out.println("Por época: " + anios(museo.recorridoPorEpoca()) + " · Destacadas: " + anios(museo.recorridoDestacadas()));
    }
}

// Ejercicio 50: AgroRiego - Strategy (R2) + Bridge (R4)
interface Programa {
    int minutos(int hora, int humedad);
}
class Horario implements Programa {
    public int minutos(int hora, int humedad) {
        if (hora == 6 || hora == 18) {
            return 20;
        }
        return 0;
    }
}
class PorHumedad implements Programa {
    public int minutos(int hora, int humedad) {
        if (humedad < 25) {
            return 30;
        }
        return 0;
    }
}
class Ahorro implements Programa {
    public int minutos(int hora, int humedad) {
        boolean esNoche = hora >= 20 || hora < 6;
        if (esNoche && humedad < 25) {
            return 15;
        }
        return 0;
    }
}
interface Valvula {
    int abrir(int minutos);
}
class Goteo implements Valvula {
    public int abrir(int minutos) {
        return 2 * minutos;
    }
}
class Aspersion implements Valvula {
    public int abrir(int minutos) {
        return 10 * minutos;
    }
}
class Controlador {
    private final Valvula valvula;
    Controlador(Valvula valvula) {
        this.valvula = valvula;
    }
    int abrir(int minutos) {
        return valvula.abrir(minutos);
    }
}
class ControlManual extends Controlador {
    ControlManual(Valvula valvula) {
        super(valvula);
    }
}
class ControlAutomatico extends Controlador {
    private final Programa programa;
    ControlAutomatico(Valvula valvula, Programa programa) {
        super(valvula);
        this.programa = programa;
    }
    int regar(int hora, int humedad) {
        int minutos = programa.minutos(hora, humedad);
        if (minutos > 0) {
            abrir(minutos);
        }
        return minutos;
    }
}
public class Main {
    public static void main(String[] args) {
        System.out.println("=== Caso 2 · Req. 2 (Strategy) ===");
        ControlAutomatico porHorario = new ControlAutomatico(new Goteo(), new Horario());
        ControlAutomatico porHumedad = new ControlAutomatico(new Goteo(), new PorHumedad());
        ControlAutomatico ahorro = new ControlAutomatico(new Goteo(), new Ahorro());
        System.out.println("Horario fijo: " + porHorario.regar(14, 22) + " min · Por humedad: " + porHumedad.regar(14, 22) + " min · Ahorro de agua: " + ahorro.regar(14, 22) + " min");
        System.out.println("\n=== Caso 4 · Req. 4 (Bridge) ===");
        ControlManual manual = new ControlManual(new Goteo());
        ControlAutomatico automatico = new ControlAutomatico(new Aspersion(), new Horario());
        System.out.println(manual.abrir(10) + " litros · " + automatico.abrir(10) + " litros");
    }
}

// ▌SINGLETON (Creacional): garantiza una única instancia de una clase y un punto de acceso global.
// ▌Roles: Singleton (constructor privado + campo estático + getInstancia()).
// ▌Como: el presidente de un país: solo hay uno y todos saben dónde encontrarlo.

// ▌FACTORY METHOD (Creacional): define una operación para crear objetos y deja que las subclases decidan cuál.
// ▌Roles: Creator (crear()), ConcreteCreator, Product, ConcreteProduct.
// ▌Como: una pizzería con sucursales: cada una decide qué masa y estilo prepara.

// ▌ABSTRACT FACTORY (Creacional): crea familias de objetos relacionados sin conocer sus clases concretas.
// ▌Roles: AbstractFactory, ConcreteFactory, AbstractProduct, ConcreteProduct.
// ▌Como: un catálogo de muebles por estilo: todo el juego es moderno o clásico, nunca mezclado.

// ▌BUILDER (Creacional): construye un objeto complejo paso a paso, con partes opcionales.
// ▌Roles: Builder, ConcreteBuilder, Director (recetas predefinidas), Product.
// ▌Como: armar una hamburguesa: eliges ingredientes, o pides el combo que ya trae la receta.

// ▌PROTOTYPE (Creacional): crea objetos nuevos copiando uno ya existente.
// ▌Roles: Prototype (clonar()), ConcretePrototype, Client.
// ▌Como: fotocopiar un formulario ya lleno y cambiar solo unos pocos datos.

// ▌ADAPTER (Estructural): convierte la interfaz de una clase en la que el cliente espera.
// ▌Roles: Target, Adaptee (clase externa), Adapter, Client.
// ▌Como: el adaptador de enchufe de viaje: el aparato no cambia, el adaptador traduce.

// ▌BRIDGE (Estructural): separa una abstracción de su implementación para que varíen por separado.
// ▌Roles: Abstraction, RefinedAbstraction, Implementor, ConcreteImplementor.
// ▌Como: control remoto y televisor: cualquier control sirve con cualquier marca de TV.

// ▌COMPOSITE (Estructural): trata igual a un objeto individual y a un grupo de objetos (árbol).
// ▌Roles: Component, Leaf (hoja), Composite (guarda hijos), Client.
// ▌Como: carpetas y archivos: pides el tamaño y la carpeta suma todo lo que contiene.

// ▌DECORATOR (Estructural): agrega responsabilidades a un objeto envolviéndolo, sin crear subclases.
// ▌Roles: Component, ConcreteComponent, Decorator, ConcreteDecorator.
// ▌Como: un café al que apilas leche, crema y canela: cada capa suma algo.

// ▌FACADE (Estructural): ofrece una interfaz simple que oculta un conjunto de subsistemas.
// ▌Roles: Facade, clases del Subsystem, Client.
// ▌Como: el botón «modo cine»: enciende TV, sonido y luces con una sola orden.

// ▌FLYWEIGHT (Estructural): comparte objetos para ahorrar memoria separando estado compartido y propio.
// ▌Roles: Flyweight (intrínseco), FlyweightFactory, Context (extrínseco), Client.
// ▌Como: las letras de una imprenta: una sola «a» se reutiliza en todo el texto.

// ▌PROXY (Estructural): un sustituto con la misma interfaz que controla el acceso al objeto real.
// ▌Roles: Subject, RealSubject, Proxy (protección, virtual o caché), Client.
// ▌Como: la secretaria de un jefe: filtra quién pasa y cuándo.

// ▌CHAIN OF RESPONSIBILITY (Comportamiento): pasa una petición por una cadena de manejadores hasta que alguien la atiende.
// ▌Roles: Handler (setSiguiente), ConcreteHandler, Client.
// ▌Como: soporte técnico por niveles: si el 1.º no puede, escala al 2.º y luego al 3.º.

// ▌COMMAND (Comportamiento): convierte una acción en un objeto para guardarla, encolarla o deshacerla.
// ▌Roles: Command (ejecutar/deshacer), ConcreteCommand, Receiver, Invoker, Client.
// ▌Como: el pedido en un restaurante: el mesero anota la orden y la cocina la ejecuta luego.

// ▌ITERATOR (Comportamiento): recorre los elementos de una colección sin exponer cómo está guardada.
// ▌Roles: Iterator (hayMas/siguiente), ConcreteIterator, Aggregate, Client.
// ▌Como: pasar las páginas de un libro: no importa cómo esté encuadernado.

// ▌MEDIATOR (Comportamiento): centraliza la comunicación entre objetos para que no se conozcan entre sí.
// ▌Roles: Mediator, ConcreteMediator, Colleague, ConcreteColleague.
// ▌Como: una torre de control: los aviones hablan con ella, nunca entre ellos.

// ▌MEMENTO (Comportamiento): captura el estado interno de un objeto para poder restaurarlo después.
// ▌Roles: Originator (guardar/restaurar), Memento (instantánea), Caretaker (la guarda).
// ▌Como: el punto de guardado de un videojuego: vuelves exactamente a ese momento.

// ▌OBSERVER (Comportamiento): avisa automáticamente a varios objetos cuando otro cambia de estado.
// ▌Roles: Subject (notificar), Observer (actualizar), ConcreteSubject, ConcreteObserver.
// ▌Como: suscribirte a un canal: cada video nuevo llega a todos los suscriptores.

// ▌STATE (Comportamiento): cambia el comportamiento de un objeto cuando cambia su estado interno.
// ▌Roles: Context, State, ConcreteState (cada uno con sus transiciones).
// ▌Como: un semáforo: según el color, la misma señal significa algo distinto.

// ▌STRATEGY (Comportamiento): encapsula algoritmos intercambiables detrás de una misma interfaz.
// ▌Roles: Strategy, ConcreteStrategy, Context (usa la estrategia elegida).
// ▌Como: elegir cómo ir a la universidad (a pie, bus o taxi): el destino es el mismo.

// ▌TEMPLATE METHOD (Comportamiento): define el esqueleto de un algoritmo y deja que las subclases rellenen pasos.
// ▌Roles: AbstractClass (método plantilla final), ConcreteClass (pasos abstractos).
// ▌Como: una receta: el orden es fijo, pero cada cocinero decide un paso.

// ▌VISITOR (Comportamiento): agrega operaciones nuevas a una jerarquía sin modificar sus clases.
// ▌Roles: Visitor, ConcreteVisitor, Element (aceptar), ConcreteElement.
// ▌Como: un inspector que visita casas, tiendas y oficinas y revisa cada tipo a su manera.

// ▌INTERPRETER (Comportamiento): representa una gramática con clases y evalúa expresiones con ella.
// ▌Roles: AbstractExpression, TerminalExpression, NonterminalExpression, Context.
// ▌Como: una calculadora: «2 + 3» se vuelve un árbol y cada nodo se evalúa.
